interface FishTankProps {
    onRewardClaim: (amount: number) => void;
    showIntro?: boolean;
}

export const FishTank: React.FC<FishTankProps> = ({ onRewardClaim, showIntro = false }) => {
    const [pepinoState, setPepinoState] = useState<PepinoState>(Storage.getPepinoState());

    // Initialize ready state immediately (Lazy initializer)
    const [isGiftReady, setIsGiftReady] = useState(() => {
        const now = Date.now();
        return now >= pepinoState.lastGiftTime + pepinoState.nextGiftDelay;
    });

    // Reward Feedback State
    const [rewardFeedback, setRewardFeedback] = useState<{amount: number} | null>(null);
    const [rewardExiting, setRewardExiting] = useState(false);
    const [clickCoords, setClickCoords] = useState<{x: number, y: number} | null>(null);

    // Hearts Interaction State
    const [hearts, setHearts] = useState<{id: number, x: number, y: number, tx: number, rot: number}[]>([]);

    // Speech Bubble State
    const [speech, setSpeech] = useState<string | null>(null);

    // Intro State: 
    // 'waiting' (text visible, user must tap) -> 'clearing' (text fades out) -> 
    // 'appearing' (fish pops in) -> 'active' (normal swim)
    const [introState, setIntroState] = useState<'waiting' | 'clearing' | 'appearing' | 'active'>(
        showIntro ? 'waiting' : 'active'
    );

    // Fish movement state
    // Initialize random position (X: 15-85%, Y: 32-85%)
    const [fishPos, setFishPos] = useState(() => ({ 
        x: 15 + Math.random() * 70, 
        y: 32 + Math.random() * 53 
    }));
    const [fishDirection, setFishDirection] = useState<'left' | 'right'>('right');

    // Container dimensions for smooth pixel-perfect transforms
    const [tankSize, setTankSize] = useState({ width: 0, height: 0 });

    // Transition Ready State (Prevents jump from 0,0)
    const [isTransitionEnabled, setIsTransitionEnabled] = useState(false);

    // Refs for animation logic to avoid stale closures
    const fishPosRef = useRef(fishPos);
    const containerRef = useRef<HTMLDivElement>(null);

    // Track container size for pixel-perfect transforms
    useEffect(() => {
        if (!containerRef.current) return;

        const updateSize = () => {
            if (containerRef.current) {
                const { width, height } = containerRef.current.getBoundingClientRect();
                setTankSize({ width, height });
            }
        };

        // Initial size
        updateSize();

        const observer = new ResizeObserver(() => {
            updateSize();
        });

        observer.observe(containerRef.current);
        return () => observer.disconnect();
    }, []);

    // Enable transitions only AFTER we have a valid size and position calculated
    // This prevents the "fly in from 0,0" visual glitch
    useEffect(() => {
        if (tankSize.width > 0 && !isTransitionEnabled) {
            // Increased timeout to 150ms to ensure DOM has fully applied the initial non-transitioned position
            const t = setTimeout(() => {
                setIsTransitionEnabled(true);
            }, 150);
            return () => clearTimeout(t);
        }
    }, [tankSize.width, isTransitionEnabled]);

    // Handle Intro Flow Init (Skip if not showing intro)
    useEffect(() => {
        if (!showIntro) {
            setIntroState('active');
        }
    }, [showIntro]);

    const handleIntroTap = () => {
        if (introState !== 'waiting') return;

        sounds.playClick(); 
        setIntroState('clearing');

        // Wait for text fade (700ms). Fade is halfway done around 350ms.
        setTimeout(() => {
            setIntroState('appearing'); 
            sounds.playPop(); 

            // Switch to fully active state after rapid pop animation (300ms)
            setTimeout(() => {
                setIntroState('active');
            }, 400); 
        }, 600); 
    };

    // Derived state for visibility
    const isTextVisible = introState === 'waiting';
    const isFishVisible = (introState === 'appearing' || introState === 'active') && tankSize.width > 0;

    // SPEECH BUBBLE LOGIC
    useEffect(() => {
        // Stop speech if:
        // 1. Fish isn't active
        // 2. A gift is ready (Priority - strict check)
        if (!isFishVisible || introState !== 'active' || isGiftReady) {
            setSpeech(null); 
            return;
        }

        let timeoutId: any;

        const runCycle = () => {
            // Double check gift status (redundant due to dependency but safe)
            if (isGiftReady) return;

            // 1. Pick random message
            const msg = PEPINO_MESSAGES[Math.floor(Math.random() * PEPINO_MESSAGES.length)];
            setSpeech(msg);

            // 2. Hide after 10 seconds
            timeoutId = setTimeout(() => {
                setSpeech(null);
                // 3. Wait 5 seconds cooldown before next message
                timeoutId = setTimeout(runCycle, 5000);
            }, 10000);
        };

        // Initial speech after 1 second of being active to give space for Gift appearance
        timeoutId = setTimeout(runCycle, 1000);

        return () => {
            clearTimeout(timeoutId);
        };
    }, [isFishVisible, introState, isGiftReady]);

    // Timer check for Gifts
    useEffect(() => {
        const checkTime = () => {
            const now = Date.now();
            const readyTime = pepinoState.lastGiftTime + pepinoState.nextGiftDelay;
            const ready = now >= readyTime;
            setIsGiftReady(ready);
        };

        checkTime();
        // Check more frequently (1s) to capture readiness as soon as possible
        const interval = setInterval(checkTime, 1000); 
        return () => clearInterval(interval);
    }, [pepinoState]);

    // Random Swimming Logic
    useEffect(() => {
        if (introState !== 'active') return;

        let timeoutId: any;

        const moveFish = () => {
            const currentX = fishPosRef.current.x;

            // Generate new target position
            // X: 15-85% (avoid walls)
            const newX = 15 + Math.random() * 70;

            // Y: Limit to lower part (avoid top 50px)
            // Tank Height = 224px (h-56)
            const newY = 32 + Math.random() * 53; 

            // Determine direction based on CURRENT position vs NEW position
            const newDirection = newX > currentX ? 'right' : 'left';

            setFishDirection(newDirection);
            setFishPos({ x: newX, y: newY });

            // Update ref
            fishPosRef.current = { x: newX, y: newY };

            const delay = 4000 + Math.random() * 4000; // Slow, calm movement
            timeoutId = setTimeout(moveFish, delay);
        };

        // Initial delay: Start quickly after active
        const startDelay = 1000;
        timeoutId = setTimeout(moveFish, startDelay);

        return () => clearTimeout(timeoutId);
    }, [introState]); 

    const handleClaim = (e: React.MouseEvent) => {
        e.stopPropagation();
        if (!isGiftReady || rewardFeedback) return;

        // Capture coordinates relative to tank
        if (containerRef.current) {
             const rect = containerRef.current.getBoundingClientRect();
             setClickCoords({
                 x: e.clientX - rect.left,
                 y: e.clientY - rect.top
             });
        }

        const minDelay = 7200000;
        const maxDelay = 10800000;
        const nextDelay = Math.floor(Math.random() * (maxDelay - minDelay + 1) + minDelay);

        Storage.updatePepinoGiftTime(nextDelay);
        setPepinoState(Storage.getPepinoState()); 
        setIsGiftReady(false);

        const r = Math.random();
        let amount = 5;

        // Reward Distribution:
        // 20 Diamonds: 5%
        // 15 Diamonds: 15%
        // 10 Diamonds: 30%
        // 5 Diamonds: 50%

        if (r < 0.05) amount = 20;
        else if (r < 0.20) amount = 15;
        else if (r < 0.50) amount = 10;
        else amount = 5;

        if (amount > 0) {
            // New "Bubbly" sound for gift
            sounds.playBubblePop();
            onRewardClaim(amount);
            showReward({ amount });
        }
    };

    const handlePepinoClick = (e: React.MouseEvent) => {
        e.stopPropagation();
        sounds.playPepinoTap(); // Play cute tap sound
        if (containerRef.current) {
            const rect = containerRef.current.getBoundingClientRect();
            const x = e.clientX - rect.left;
            const y = e.clientY - rect.top;

            // Random horizontal movement (-60px to +60px)
            const tx = (Math.random() - 0.5) * 120;
            // Random rotation (-30deg to +30deg)
            const rot = (Math.random() - 0.5) * 60;

            const newHeart = { id: Date.now() + Math.random(), x, y, tx, rot };
            setHearts(prev => [...prev, newHeart]);

            setTimeout(() => {
                setHearts(prev => prev.filter(h => h.id !== newHeart.id));
            }, 800);
        }
    };

    const showReward = (feedback: {amount: number}) => {
        setRewardFeedback(feedback);
        setRewardExiting(false);

        // Show for 2 seconds total
        setTimeout(() => {
            setRewardExiting(true);
            setTimeout(() => {
                setRewardFeedback(null);
                setRewardExiting(false);
                setClickCoords(null);
            }, 300); 
        }, 1700);
    };


    // Scale Logic: 0 during wait/clear, 1 during appear/active
    const scaleValue = (introState === 'waiting' || introState === 'clearing') ? 0 : 1;

    // Transition Duration Logic
    const transitionDuration = introState === 'active' ? '4000ms' : '300ms';

    // Calculate Exact Pixel Coordinates for Transform
    // Fish is w-12 (48px) x h-8 (32px). Center offset is 24px, 16px.
    const fishX = (fishPos.x / 100) * tankSize.width - 24;
    const fishY = (fishPos.y / 100) * tankSize.height - 16;

    return (
        <div 
            ref={containerRef}
            // Size: w-24 h-16 (~20-25% smaller than original w-32 h-24)
            className="w-full h-56 relative rounded-[1.75rem] overflow-hidden bg-[#e0f7fa] shadow-xl mb-6 select-none animate-pop mx-auto"
        >
            <style>{`
                @keyframes heart-float {
                    0% { transform: translate(-50%, -50%) scale(1); opacity: 1; }
                    100% { transform: translate(calc(-50% + var(--tx)), calc(-50% - 75px)) scale(1.1) rotate(var(--rot)); opacity: 0; }
                }
            `}</style>

            {/* Clean Water Gradient */}
            <div className="absolute inset-0 bg-gradient-to-b from-[#e0f7fa] via-[#d1f4fa] to-[#b3e5fc]" />

            {/* --- LAYER 1: BACKGROUND PLANTS (Behind Fish) --- */}
            {/* Z-Index 5: Behind Fish (30) */}
            <div className="absolute inset-x-0 bottom-0 h-full z-[5] pointer-events-none">
                {/* Background Plants Cluster */}
                {/* Added translate3d(0,0,0) to force layer promotion and fix vibration on iOS */}
                <div 
                    className="absolute bottom-4 left-[10%] w-24 h-[60%] opacity-80 mix-blend-multiply origin-bottom"
                    style={{ transform: 'translate3d(0,0,0)' }}
                >
                     <svg className="w-full h-full overflow-visible" viewBox="0 0 100 100" preserveAspectRatio="none">
                        <defs>
                            <linearGradient id="plantGradientBg" x1="0.5" x2="0.5" y1="0" y2="1">
                                <stop offset="0%" stopColor="#4ade80" /> {/* green-400 */}
                                <stop offset="100%" stopColor="#14532d" /> {/* green-900 */}
                            </linearGradient>
                        </defs>

                        {/* Leaf 2 (Left - Thicker Base) */}
                        <g 
                            className="origin-bottom animate-sway" 
                            style={{ transformOrigin: '30% 100%', animationDelay: '-1.5s', willChange: 'transform' }}
                        >
                           <path d="M 24 100 C 24 70 30 40 25 15 L 27 15 C 33 30 40 60 36 100 Z" fill="url(#plantGradientBg)" opacity="0.8" />
                        </g>

                        {/* Leaf 3 (Right - Thicker Base) */}
                        <g 
                            className="origin-bottom animate-sway-slow" 
                            style={{ transformOrigin: '70% 100%', animationDelay: '-3s', willChange: 'transform' }}
                        >
                           <path d="M 69 100 C 69 70 75 40 78 15 L 80 15 C 85 40 81 70 81 100 Z" fill="url(#plantGradientBg)" opacity="0.9" />
                        </g>
                     </svg>
                </div>
            </div>

            {/* --- INTRO TEXT OVERLAY --- */}
            <div 
                onClick={handleIntroTap}
                className={`absolute inset-0 flex items-center justify-center p-4 z-40 transition-opacity duration-700 cursor-pointer active:scale-95 ${isTextVisible ? 'opacity-100' : 'opacity-0 pointer-events-none'}`}
            >
                <div className="bg-white/60 backdrop-blur-md p-6 rounded-2xl shadow-sm border border-white/40 text-center max-w-[90%]">
                    <p className="text-xl font-bold text-stone-800 mb-3 leading-tight">Meet Pepino.</p>
                    <p className="text-sm font-medium text-stone-600 mb-1 leading-relaxed">He was around when Oku was being built.</p>
                    <p className="text-sm font-medium text-stone-600 leading-relaxed mb-4">Feel free to check on him anytime.</p>
                    <p className="text-xs font-bold text-blue-500 uppercase tracking-widest animate-pulse">Tap to continue</p>
                </div>
            </div>

            {/* PEPINO CONTAINER (Handles Position via Transform) */}
            {/* Z-Index 30: In front of Back Plants (5), Behind Front Plant (35) */}
            <div 
                onClick={handlePepinoClick}
                className={`absolute w-12 h-8 z-30 cursor-pointer top-0 left-0 ${isFishVisible ? 'opacity-100' : 'opacity-0'}`}
                style={{ 
                    // CRITICAL FIX: Use translate3d with pixels for smooth iOS movement
                    // Removed 'opacity' from transition to prevent fade-in effect on subsequent moves
                    transform: `translate3d(${fishX}px, ${fishY}px, 0)`,
                    transition: isTransitionEnabled ? `transform ${transitionDuration} ease-in-out` : 'none',
                    willChange: 'transform',
                    WebkitBackfaceVisibility: 'hidden',
                    backfaceVisibility: 'hidden',
                }}
            >
                 {/* POP IN ANIMATION WRAPPER (Handles Scale) */}
                 <div 
                    className="w-full h-full transition-transform duration-300 cubic-bezier(0.175, 0.885, 0.32, 1.275)"
                    style={{ transform: `scale(${scaleValue})` }}
                 >

                     {/* DIRECTION FLIPPER */}
                     <div 
                        className="w-full h-full transition-transform duration-500"
                        style={{ transform: fishDirection === 'left' ? 'scaleX(-1)' : 'scaleX(1)' }}
                     >
                         {/* WIGGLER */}
                         <div className="w-full h-full animate-wiggle" style={{ willChange: 'transform' }}>
                            {/* Pepino SVG */}
                            <svg viewBox="344.5149 210.9059 74.9591 41.2278" className="w-full h-full drop-shadow-sm filter" style={{ filter: 'drop-shadow(0 4px 6px rgba(0,0,0,0.1))' }}>
                                <path d="M 373.193 239.648 C 379.513 254.112 400.131 252.185 404.661 240.061 C 393.45 240.02 396.193 239.089 386.193 239.648 L 373.193 239.648 Z" fill="#ef4444" opacity="0.95" style={{strokeWidth: 1}} transform="matrix(1, 0, 0, 1, 0, -1.4210854715202004e-14)"/>
                                <path d="M 372.793 224.525 C 379.113 207.278 399.731 209.576 404.261 224.033 C 393.05 224.081 395.793 225.192 385.793 224.525 L 372.793 224.525 Z" fill="#ef4444" opacity="0.95" style={{strokeWidth: 1}} transform="matrix(1, 0, 0, 1, 0, -1.4210854715202004e-14)"/>
                                <path d="M 394.515 231.681 C 379.515 206.681 344.428 201.406 344.515 231.681 C 344.565 261.131 379.515 256.681 394.515 231.681 Z" fill="#ef4444" opacity="0.95" style={{strokeWidth: 1}} transform="matrix(1, 0, 0, 1, 0, -1.4210854715202004e-14)"/>
                                <path d="M 394.515 231.681 C 374.515 216.681 359.515 211.681 354.515 231.681 C 359.515 251.681 374.515 246.681 394.515 231.681 Z" fill="#b91c1c" opacity="0.15" style={{strokeWidth: 1}} transform="matrix(1, 0, 0, 1, 0, -1.4210854715202004e-14)"/>
                                <ellipse cx="391.474" cy="231.681" rx="28" ry="11" fill="#dc2626" style={{strokeWidth: 1}} transform="matrix(1, 0, 0, 1, 0, -1.4210854715202004e-14)"/>
                                <path d="M 401.174 234.169 C 395.84 239.502 397.84 240.836 407.174 238.169 L 401.174 234.169 Z" fill="#fca5a5" opacity="0.8" style={{strokeWidth: 1, transformOrigin: '402.719px 236.836px'}} transform="matrix(0.71619296, -0.69790214, 0.69790214, 0.71619296, 0.00000291, 0.0000368)"/>
                                <circle cx="411.874" cy="230.381" r="2.5" fill="black" style={{strokeWidth: 1}} transform="matrix(1, 0, 0, 1, 0, -1.4210854715202004e-14)"/>
                                <circle cx="412.874" cy="229.381" r="0.8" fill="white" opacity="0.9" style={{strokeWidth: 1}} transform="matrix(1, 0, 0, 1, 0, -1.4210854715202004e-14)"/>
                            </svg>
                         </div>
                     </div>
                 </div>

                 {/* SPEECH BUBBLE */}
                 {/* Positioned relative to Fish Container (Upright) */}
                 <AnimatePresence>
                    {speech && !isGiftReady && (
                        <motion.div 
                            initial={{ opacity: 0, scale: 0, y: 10, x: "-50%" }} 
                            animate={{ opacity: 1, scale: 1, y: 0, x: "-50%" }}
                            exit={{ opacity: 0, scale: 0, y: 5, x: "-50%" }}
                            transition={{ duration: 0.2 }}
                            className="absolute -top-10 left-1/2 whitespace-nowrap z-50 origin-bottom"
                        >
                            <div className="bg-white/95 backdrop-blur-sm px-3 py-1.5 rounded-xl shadow-md border border-stone-100 text-[10px] font-bold text-stone-600 relative">
                                {speech}
                                {/* Tiny triangle */}
                                <div className="absolute top-full left-1/2 -translate-x-1/2 w-0 h-0 border-[5px] border-transparent border-t-white/95"></div>
                            </div>
                        </motion.div>
                    )}
                 </AnimatePresence>

                 {/* GIFT BUBBLE (Trigger) - Only visible when fish is visible */}
                 {isGiftReady && isFishVisible && !isTextVisible && (
                        <div 
                            // Moved down (-top-7 vs -top-10) and right (ml-4)
                            className="absolute -top-7 left-1/2 -translate-x-1/2 ml-4 z-20"
                            // No scaling/transform logic here, just centering relative to upright container
                            style={{ backfaceVisibility: 'hidden' }}
                        >
                             <div className="animate-scale-in origin-bottom">
                                <div 
                                    onClick={handleClaim}
                                    className="cursor-pointer hover:scale-110 transition-transform duration-200"
                                >
                                    <div className="bg-white/90 backdrop-blur-sm p-1.5 rounded-full shadow-md border border-blue-100/50">
                                        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="#3b82f6" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                                            <rect x="3" y="8" width="18" height="4" rx="1" />
                                            <path d="M12 8v13" />
                                            <path d="M19 12v7a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2v-7" />
                                            <path d="M7.5 8a2.5 2.5 0 0 1 0-5A4.8 8 0 0 1 12 8a4.8 8 0 0 1 4.5-5 2.5 2.5 0 0 1 0 5" />
                                        </svg>
                                    </div>
                                </div>
                             </div>
                        </div>
                 )}
            </div>

            {/* --- LAYER 2: FOREGROUND PLANT (In Front of Fish) --- */}
            {/* Z-Index 35: In front of Fish (30), Behind Scenery (40) */}
            <div className="absolute inset-x-0 bottom-0 h-full z-[35] pointer-events-none">
                {/* Added translate3d(0,0,0) to force layer promotion and fix vibration on iOS */}
                <div 
                    className="absolute bottom-4 left-[10%] w-24 h-[60%] opacity-80 mix-blend-multiply origin-bottom"
                    style={{ transform: 'translate3d(0,0,0)' }}
                >
                     <svg className="w-full h-full overflow-visible" viewBox="0 0 100 100" preserveAspectRatio="none">
                        <defs>
                            <linearGradient id="plantGradientFg" x1="0.5" x2="0.5" y1="0" y2="1">
                                <stop offset="0%" stopColor="#4ade80" /> {/* green-400 */}
                                <stop offset="100%" stopColor="#14532d" /> {/* green-900 */}
                            </linearGradient>
                        </defs>

                        {/* Leaf 1 (Main Tall - Thicker Base) */}
                        <g 
                            className="origin-bottom animate-sway-slow" 
                            style={{ transformOrigin: '50% 100%', willChange: 'transform' }}
                        >
                           <path d="M 42 100 C 42 60 50 30 48 5 L 50 5 C 50 30 58 60 58 100 Z" fill="url(#plantGradientFg)" />
                        </g>
                     </svg>
                </div>
            </div>

            {/* --- SCENERY LAYER (Sand & Rocks) --- */}
            {/* Z-Index 40: Frontmost Layer (Covers plant bases & fish if low) */}
            <div className="absolute inset-x-0 bottom-0 h-20 z-40 pointer-events-none">

                {/* Background Rock (New Tall Rock) - Lighter color for depth, positioned behind */}
                {/* Adjusted right position from 4% to 8% to move it slightly left */}
                <div className="absolute bottom-1 right-[8%] w-16 h-14 bg-gradient-to-t from-[#a8a29e] to-[#d6d3d1] rounded-[30%_70%_70%_30%_/_30%_50%_50%_70%] rotate-[-8deg] z-0" />

                {/* Left Rock */}
                <div className="absolute bottom-2 left-[12%] w-12 h-8 bg-gradient-to-tr from-[#7d7873] to-[#a8a29e] rounded-[45%_55%_50%_50%_/_50%_50%_40%_40%] rotate-2 shadow-sm z-10" />

                {/* Right Small Rock (Foreground) */}
                <div className="absolute bottom-1 right-[18%] w-9 h-7 bg-gradient-to-tl from-[#8a8580] to-[#b5b0ab] rounded-[50%_50%_40%_60%] -rotate-3 shadow-sm z-10" />

                {/* Center Pebble */}
                <div className="absolute bottom-3 left-[45%] w-5 h-4 bg-gradient-to-t from-[#96918c] to-[#c2bdb8] rounded-full z-10" />

                {/* Sand Layer */}
                <svg className="absolute bottom-0 w-full h-full z-[20]" preserveAspectRatio="none" viewBox="0 0 100 100">
                    <defs>
                        <linearGradient id="sandGradient" x1="0" x2="0" y1="0" y2="1">
                            <stop offset="0%" stopColor="#f7eed9" /> {/* Very Light Sand */}
                            <stop offset="100%" stopColor="#ebe0c5" /> {/* Slightly Darker */}
                        </linearGradient>
                    </defs>
                    {/* Gentle Wave: Starts around y=75 (approx 15-20px high in h-20/80px container, which is ~10% of tank) */}
                    <path d="M0 100 L0 75 Q 30 82 50 78 T 100 72 L 100 100 Z" fill="url(#sandGradient)" />
                </svg>
            </div>

            {/* Hearts Layer */}
            {hearts.map(h => (
                <div 
                    key={h.id} 
                    className="absolute z-[60] pointer-events-none text-rose-500"
                    style={{ 
                        left: h.x, 
                        top: h.y,
                        '--tx': `${h.tx}px`,
                        '--rot': `${h.rot}deg`,
                        animation: 'heart-float 0.8s ease-out forwards'
                    } as React.CSSProperties}
                >
                    <svg viewBox="0 0 24 24" fill="currentColor" className="w-5 h-5 drop-shadow-sm">
                        <path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z"/>
                    </svg>
                </div>
            ))}

            {/* REWARD FEEDBACK (Dynamic Position) */}
            {rewardFeedback && clickCoords && (
                <div 
                    className="absolute z-50 pointer-events-none"
                    style={{ left: clickCoords.x, top: clickCoords.y - 20 }}
                >
                    <div 
                        className={`transition-all duration-300 ease-out ${
                            rewardExiting 
                            ? 'opacity-0 scale-90' 
                            : 'opacity-100 scale-100'
                        }`}
                    >
                        <div className="bg-white px-2.5 py-1 rounded-full shadow-lg flex items-center gap-1.5 border border-stone-100 animate-scale-in origin-center">
                            <>
                                <span className="text-xs font-bold text-stone-800">+{rewardFeedback.amount}</span>
                                <Icons.Diamond className="w-2.5 h-2.5 text-blue-500 fill-current" />
                            </>
                        </div>
                    </div>
                </div>
            )}

            {/* Tank Reflection */}
            <div className="absolute top-0 right-0 w-32 h-32 bg-gradient-to-bl from-white/30 to-transparent pointer-events-none rounded-bl-full" />
        </div>
    );
};

import React, { useState } from 'react';
import { Icons } from '../ui/Icons';
import { DIAMOND_OFFERS } from '../../utils/constants';
import { DiamondOffer } from '../../types';
import { Storage } from '../../utils/storage';
import { FishTank } from '../ui/FishTank';
import { AnimatedNumber } from '../ui/AnimatedNumber';

interface DiamondShopScreenProps {
    points: number;
    onBack: () => void;
    onWatchAd: () => void;
    onBuyOffer: (offer: DiamondOffer) => void;
    onEarnPoints: (amount: number) => void;
    starterPackPurchased: boolean;
}

const DiamondBackground = () => (
  <div className="absolute inset-0 overflow-hidden pointer-events-none z-0">
    <svg className="w-full h-[200%] animate-flow-up opacity-[0.15]" xmlns="http://www.w3.org/2000/svg">
      <defs>
        <pattern id="diamond-pattern" x="0" y="0" width="60" height="60" patternUnits="userSpaceOnUse">
           <path d="M30 5 L55 30 L30 55 L5 30 Z" fill="none" stroke="currentColor" strokeWidth="2" className="text-stone-400 dark:text-stone-600" />
        </pattern>
      </defs>
      <rect width="100%" height="100%" fill="url(#diamond-pattern)" />
    </svg>
  </div>
);

export const DiamondShopScreen: React.FC<DiamondShopScreenProps> = ({
    points,
    onBack,
    onWatchAd,
    onBuyOffer,
    onEarnPoints,
    starterPackPurchased
}) => {
    const pepinoState = Storage.getPepinoState();

    const handleBuyOfferWrapper = (offer: DiamondOffer) => {
        onBuyOffer(offer);
    };

    const shouldShowIntro = () => {
        if (!pepinoState.unlocked) return false;
        const now = Date.now();
        // If unlocked within the last 15 seconds AND delay is 0 (initial state), show intro
        return (now - pepinoState.lastGiftTime) < 15000 && pepinoState.nextGiftDelay === 0;
    };

    const handleRewardClaim = (amount: number) => {
        if (amount > 0) {
            onEarnPoints(amount);
        }
    };

    // Unified Price Badge Style
    // Premium Silver Gradient + Dark Text + Thin Border + Reduced Size
    const priceBadgeClass = "px-3 py-1.5 rounded-lg text-sm font-bold text-stone-800 shadow-sm min-w-[70px] text-center flex items-center justify-center border border-stone-900/10 bg-gradient-to-br from-white via-gray-100 to-gray-200 active:scale-95 transition-transform tracking-wide";

    return (
        <div className="flex-1 w-full flex flex-col items-center overflow-hidden relative">
            <DiamondBackground />

            <div className="w-full max-w-md flex items-center justify-between px-6 pt-4 pb-4 relative shrink-0 z-20 mx-auto">
                <button onClick={onBack} className="p-2 rounded-full hover:bg-stone-200 transition -ml-2 text-t-icon relative z-30">
                    <Icons.Back className="w-6 h-6 text-t-icon" />
                </button>

                <div className="flex flex-col items-center absolute left-0 right-0 pointer-events-none z-20">
                    <h1 className="text-xl font-bold text-t-primary leading-none">Diamond Shop</h1>
                    <p className="text-t-secondary text-[10px] font-bold tracking-widest uppercase mt-1">Get More</p>
                </div>

                <div className="flex items-center gap-1 bg-t-surface px-3 py-2 rounded-full shadow-sm relative z-30">
                      <AnimatedNumber value={points} className="text-sm font-bold text-t-primary tabular-nums" />
                      <div className="text-blue-500"><Icons.Diamond className="w-3 h-3 fill-current" /></div>
                </div>
            </div>

            <div className="flex-1 w-full overflow-y-auto px-6 pb-6 hide-scrollbar flex flex-col items-center relative z-10">
                <div className="w-full max-w-md pt-2 mx-auto">

                    {pepinoState.unlocked ? (
                        <FishTank onRewardClaim={handleRewardClaim} showIntro={shouldShowIntro()} />
                    ) : (
                        DIAMOND_OFFERS.filter(o => o.type === 'support').map(offer => (
                            <button 
                                key={offer.id} 
                                onClick={() => handleBuyOfferWrapper(offer)}
                                // Card Container - Premium Midnight Slate Gradient with lighter start
                                className="w-full h-56 relative overflow-hidden rounded-[1.75rem] p-6 shadow-2xl transition-transform mb-6 text-left bg-gradient-to-br from-slate-600 via-slate-800 to-slate-900 active:scale-[0.99] group border border-white/10"
                            >
                                {/* Subtle Shine Effect */}
                                <div className="absolute inset-0 bg-gradient-to-tr from-white/0 via-white/0 to-white/5 pointer-events-none" />

                                {/* Giant Faded Heart Background - Centered/Right */}
                                <div className="absolute -right-8 -bottom-10 opacity-[0.08] pointer-events-none z-0">
                                     <svg viewBox="0 0 24 24" className="w-64 h-64 fill-current text-rose-500">
                                         <path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z"/>
                                     </svg>
                                </div>

                                {/* Moving Floating Hearts */}
                                <div className="absolute inset-0 overflow-hidden pointer-events-none z-0">
                                    {[...Array(12)].map((_, i) => (
                                        <div 
                                            key={i}
                                            className="absolute text-rose-500 animate-float-up"
                                            style={{
                                                left: `${Math.random() * 100}%`,
                                                bottom: '-20px',
                                                animationDelay: `${Math.random() * 5}s`,
                                                animationDuration: `${5 + Math.random() * 5}s`,
                                                opacity: 0 // Initial opacity handled by keyframe
                                            }}
                                        >
                                            <Icons.Heart 
                                                className="fill-current" 
                                                style={{ 
                                                    // Increased size by ~15% (range: 10px - 24px)
                                                    width: `${10 + Math.random() * 14}px`, 
                                                    height: `${10 + Math.random() * 14}px` 
                                                }}
                                            />
                                        </div>
                                    ))}
                                </div>

                                <div className="relative z-10 flex flex-col h-full">
                                    {/* Header Row */}
                                    <div className="flex justify-between items-start mb-2">
                                        <h2 className="text-2xl font-bold text-white leading-tight">{offer.title}</h2>
                                    </div>

                                    {/* Description Text - Explicitly over the heart area */}
                                    <p className="text-[10px] font-medium text-slate-300 leading-relaxed pr-2 max-w-full mb-3 relative z-10">
                                        Oku is the work of a single independent developer. Your support keeps the experience calm, fair, and ad-light. By getting this, you adopt a special companion who brings exclusive rewards to your journey. Thank you!
                                    </p>

                                    {/* Bottom Area: Benefits List + Price Badge */}
                                    <div className="flex items-end justify-between mt-auto w-full">

                                        {/* Benefits List (Smaller Text: text-[11px] or text-xs) */}
                                        <div className="flex flex-col gap-1">
                                            <div className="flex items-center gap-2">
                                                <Icons.Check className="w-3.5 h-3.5 text-emerald-400 stroke-[3]" />
                                                <div className="flex items-center gap-0.5">
                                                    <span className="text-[11px] font-bold text-white">+400</span>
                                                    <Icons.Diamond className="w-3.5 h-3.5 text-sky-400 fill-current" />
                                                </div>
                                            </div>
                                            <div className="flex items-center gap-2">
                                                <Icons.Check className="w-3.5 h-3.5 text-emerald-400 stroke-[3]" />
                                                <span className="text-[11px] font-bold text-slate-200">No forced ads, ever</span>
                                            </div>
                                            <div className="flex items-center gap-2">
                                                <Icons.Check className="w-3.5 h-3.5 text-emerald-400 stroke-[3]" />
                                                <span className="text-[11px] font-bold text-slate-200">Special companion</span>
                                            </div>
                                            <div className="flex items-center gap-2">
                                                <Icons.Check className="w-3.5 h-3.5 text-emerald-400 stroke-[3]" />
                                                <span className="text-[11px] font-bold text-slate-200">A personal thank-you</span>
                                            </div>
                                        </div>

                                        {/* Price Badge */}
                                        <div className={`${priceBadgeClass} shrink-0 ml-4 mb-0.5 shadow-lg`}>
                                            {offer.priceLabel}
                                        </div>
                                    </div>
                                </div>
                            </button>
                        ))
                    )}

                    <button 
                        onClick={onWatchAd} 
                        className="w-1/2 mx-auto block relative overflow-hidden bg-gradient-to-br from-amber-200 via-yellow-400 to-amber-500 bg-[length:200%_200%] animate-gradient rounded-2xl shadow-lg shadow-amber-500/30 active:scale-95 transition-transform group mb-8 border-t border-white/40"
                    >
                        <div className="py-3 flex items-center justify-center gap-3 relative z-10">
                            <div className="p-2 bg-white/20 rounded-xl backdrop-blur-sm border border-white/20 shadow-sm">
                                <Icons.Film className="w-6 h-6 text-stone-900" />
                            </div>

                            <div className="flex items-center gap-1.5 bg-white/30 px-3 py-1.5 rounded-xl backdrop-blur-md border border-white/20 shadow-sm">
                                 <span className="text-2xl font-bold tracking-tighter leading-none text-black">+25</span>
                                 <Icons.Diamond className="w-5 h-5 fill-current text-blue-600 drop-shadow-sm" />
                            </div>
                        </div>
                        <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/50 to-transparent z-20 animate-shimmer pointer-events-none" />
                    </button>

                    {DIAMOND_OFFERS.filter(o => o.type === 'starter').map(offer => {
                         const isPurchased = starterPackPurchased;
                         return (
                             <button 
                                key={offer.id} 
                                onClick={() => !isPurchased && onBuyOffer(offer)}
                                disabled={isPurchased}
                                className={`w-full h-40 relative overflow-hidden rounded-[1.75rem] p-5 shadow-xl transition-transform mb-6 text-left ${offer.gradientClass || 'bg-white'} ${isPurchased ? 'shadow-none opacity-50 grayscale cursor-not-allowed' : 'shadow-amber-900/5 active:scale-[0.99] group'}`}
                             >
                                <div className="absolute right-3 -bottom-10 opacity-[0.07] pointer-events-none animate-spin-slow">
                                     <Icons.Diamond className="w-48 h-48 text-stone-900 fill-current" />
                                </div>
                                <div className="relative z-10 flex flex-row justify-between h-full items-stretch">
                                    <div className="flex flex-col items-start justify-between flex-1 pr-4 py-0.5">
                                         <div>
                                             {!isPurchased && (
                                                <div className="inline-block px-2 py-0.5 rounded-md bg-orange-100 text-orange-700 text-[10px] font-bold tracking-widest uppercase mb-1.5 border border-orange-200/50 leading-none">
                                                    {offer.badge || "BEST VALUE"}
                                                </div>
                                             )}
                                             <h2 className="text-xl font-bold text-stone-900 leading-tight mb-0.5">{offer.title}</h2>
                                             <p className="text-xs font-semibold text-stone-500 leading-none">{offer.subtitle}</p>
                                         </div>
                                         <div className="flex flex-col gap-1 items-start mt-1">
                                             {offer.includes && offer.includes.map(inc => (
                                                 <div key={inc} className="flex items-center gap-1.5">
                                                     <Icons.Check className="w-3.5 h-3.5 text-green-600 stroke-[3]" />
                                                     <span className="text-[11px] font-bold text-stone-600">{inc}</span>
                                                 </div>
                                             ))}
                                         </div>
                                    </div>
                                    <div className="flex flex-col items-end justify-between shrink-0 py-0.5">
                                        <div 
                                            className={`${isPurchased ? 'bg-stone-400 text-white shadow-none cursor-default px-3 py-1.5 rounded-lg text-xs font-bold min-w-[70px] text-center border border-transparent' : priceBadgeClass}`}
                                         >
                                            {isPurchased ? 'OWNED' : offer.priceLabel}
                                         </div>
                                         <div className="flex items-center gap-1 mt-auto pt-1">
                                             <span className="text-3xl font-bold text-stone-900 tracking-tighter leading-none">+{offer.diamonds}</span>
                                             <Icons.Diamond className="w-6 h-6 text-blue-500 fill-current drop-shadow-sm mb-0.5" />
                                         </div>
                                    </div>
                                </div>
                            </button>
                        );
                    })}

                    <h3 className="text-xs font-bold text-t-secondary uppercase tracking-widest mb-3 ml-1">PACKS</h3>
                    <div className="grid grid-cols-4 gap-2 mb-8">
                        {DIAMOND_OFFERS.filter(o => o.type === 'pack').map(offer => (
                            <button 
                                key={offer.id} 
                                onClick={() => onBuyOffer(offer)}
                                className="bg-gradient-to-b from-blue-50 to-white dark:from-stone-800 dark:to-stone-900 rounded-2xl p-1.5 flex flex-col items-center justify-between shadow-sm border border-blue-100 dark:border-stone-700 h-28 active:scale-95 transition-transform group"
                            >
                                <div className="flex-1 flex flex-col items-center justify-center gap-0.5 w-full overflow-hidden">
