import { MouseEventHandler, useEffect, useRef, useState } from 'react';
import { useMediaQuery } from 'react-responsive';

const FishTank: React.FC = () => {
    const [isMobile, setIsMobile] = useState(false);
    const [isHovered, setIsHovered] = useState(false);
    const [showTapToContinue, setShowTapToContinue] = useState(true);
    const isSmallScreen = useMediaQuery({ maxWidth: 768 });
    const fishRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        setIsMobile(isSmallScreen);
    }, [isSmallScreen]);

    const handleFishClick: MouseEventHandler<HTMLDivElement> = () => {
        if (!isMobile) {
            setIsHovered(true);
            setTimeout(() => {
                setIsHovered(false);
            }, 500);
        }
    };

    const handleTapToContinue = () => {
        setShowTapToContinue(false);
    };

    return (
        <div className="relative w-full h-full">
            <div className={`absolute inset-0 bg-gradient-to-br from-blue-300 to-green-200 ${isHovered ? 'opacity-20' : 'opacity-100'} transition-opacity duration-500`} />
            <div
                ref={fishRef}
                className={`absolute inset-0 bg-transparent flex items-center justify-center cursor-pointer transition-transform duration-500 ${isHovered ? 'scale-105' : 'scale-100'}`}
                onClick={handleFishClick}
            >
                <img
                    src="https://res.cloudinary.com/dvlsyq04b/image/upload/v1711202868/oku/fish-2_n0j4ll.png"
                    alt="Fish"
                    className="w-full h-full object-contain"
                />
            </div>

            <div className="absolute inset-0 flex items-center justify-center p-4">
                <div className="bg-white bg-opacity-70 backdrop-blur-md rounded-lg shadow-md p-4 text-center">
                    <p className="text-xl leading-tight">Meet Pepino.</p>
                    <p className="text-[11px] font-medium text-stone-600 mb-1 leading-relaxed">He was around when Oku was being built.</p>
                    <p className="text-[11px] font-medium text-stone-600 leading-relaxed mb-4">Feel free to check on him after every game.</p>
                    <p className="text-xs font-bold text-blue-500 uppercase tracking-widest animate-pulse">Tap to continue</p>
                </div>
            </div>

            {/* ... (Rest of component unchanged) ... */}
        </div>
    );
};

export default FishTank;
]]></content>
</change>
</changes>
