        sounds.playClick();
        setActiveDoc(null);
    };

    const handleDevComplete = async () => {
        if(confirm("DEV TOOL: Complete 300 Super Easy levels & Add 50k Gems?")) {
            await Storage.debugCompleteLevels(Difficulty.SuperEasy, 300);
            window.location.reload();
