import React, { useState, useEffect } from 'react';
import { Difficulty, AppSettings, DiamondOffer } from './types';
import { SudokuGame } from './components/SudokuGame';
import { Storage } from './utils/storage';
import { sounds } from './utils/sound';
import { getPackCost, NUMBER_COLORS, ALL_BACKGROUNDS } from './utils/constants';
import { motion, AnimatePresence, Variants } from 'framer-motion';

// UI Components
import { PurchaseModal, ReplayModal, NotEnoughPointsModal, SettingsModal, PaymentModal } from './components/ui/Modals';
import { AdOverlay } from './components/ui/AdOverlay';

// Screens
import { SplashScreen } from './components/screens/SplashScreen';
import { DifficultyScreen } from './components/screens/DifficultyScreen';
import { LevelsScreen } from './components/screens/LevelsScreen';
import { StoreScreen } from './components/screens/StoreScreen';
import { DiamondShopScreen } from './components/screens/DiamondShopScreen';
import { StatsScreen } from './components/screens/StatsScreen';

type Screen = 'splash' | 'difficulty' | 'levels' | 'game' | 'settings' | 'store' | 'diamondShop' | 'stats';

// Optimized Diamond Background Component (CSS-based)
const DiamondBackground = () => (
  <div className="fixed inset-0 pointer-events-none z-0 bg-diamond-pattern" />
);

export function App() {
  const [screen, setScreen] = useState<Screen>('splash');
  const [direction, setDirection] = useState<number>(0);
  const [selectedDifficulty, setSelectedDifficulty] = useState<Difficulty | null>(null);
  const [selectedLevel, setSelectedLevel] = useState<number | null>(null);
  const [settings, setSettings] = useState<AppSettings>(Storage.getSettings());
  const [points, setPoints] = useState<number>(Storage.getPoints());

  const [purchasedBackgrounds, setPurchasedBackgrounds] = useState<string[]>(Storage.getPurchasedBackgrounds());
  const [selectedBackgroundId, setSelectedBackgroundId] = useState<string | null>(Storage.getSelectedBackground());

  const [purchasedNumberColors, setPurchasedNumberColors] = useState<string[]>(Storage.getPurchasedNumberColors());
  const [selectedNumberColorId, setSelectedNumberColorId] = useState<string>(Storage.getSelectedNumberColor());

  const [purchasedSoundPacks, setPurchasedSoundPacks] = useState<string[]>(Storage.getPurchasedSoundPacks());
  const [selectedSoundPackId, setSelectedSoundPackId] = useState<string>(Storage.getSelectedSoundPack());

  const [purchasedSkills, setPurchasedSkills] = useState<string[]>(Storage.getPurchasedSkills());
  const [enabledSkills, setEnabledSkills] = useState<string[]>(Storage.getEnabledSkills());
  const [starterPackPurchased, setStarterPackPurchased] = useState<boolean>(Storage.isStarterPackPurchased());

  // Unlocked Packs State - For Immediate UI Reactivity
  const [unlockedPacks2, setUnlockedPacks2] = useState<string[]>(Storage.getUnlockedPacks2());
  const [unlockedPacks3, setUnlockedPacks3] = useState<string[]>(Storage.getUnlockedPacks3());

  const [showSettings, setShowSettings] = useState(false);
  const [replayLevelId, setReplayLevelId] = useState<number | null>(null);

  const [purchaseCandidate, setPurchaseCandidate] = useState<{id: string, name: string, cost: number, type: 'bg' | 'num' | 'skill' | 'sound', description?: string} | null>(null);
  const [paymentOffer, setPaymentOffer] = useState<DiamondOffer | null>(null);

  const [showNotEnoughPoints, setShowNotEnoughPoints] = useState(false);
  const [isWatchingAd, setIsWatchingAd] = useState(false);

  const [nextBonusClaimTime, setNextBonusClaimTime] = useState(Storage.getNextBonusClaimTime());

  // Initialize Native Storage
  useEffect(() => {
    const initStorage = async () => {
        // Initialize native storage
        await Storage.initializeNative();

        // TEMP: Auto-complete Super Easy for testing
        await Storage.debugCompleteLevels(Difficulty.SuperEasy, 300);

        // Get updated data
        const data = Storage.getStoredData();

        setPoints(data.points);
        setSettings(data.settings);
        setPurchasedBackgrounds(data.purchasedBackgrounds);
        setPurchasedNumberColors(data.purchasedNumberColors);
        setPurchasedSoundPacks(data.purchasedSoundPacks || ['snd-zen']);
        setSelectedSoundPackId(data.selectedSoundPack || 'snd-zen');
        setPurchasedSkills(data.purchasedSkills);
        setEnabledSkills(data.enabledSkills || [...data.purchasedSkills]);
        setStarterPackPurchased(data.starterPackPurchased || false);
        setUnlockedPacks2(data.unlockedPack2 || []);
        setUnlockedPacks3(data.unlockedPack3 || []);
        setNextBonusClaimTime(data.nextBonusClaimTime || 0);

        const isDark = data.settings.appearance === 'dark' || (data.settings.appearance === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches);
        if (isDark) document.documentElement.classList.add('dark');
        else document.documentElement.classList.remove('dark');
    };
    initStorage();
  }, []);

  // Theme Detection
  useEffect(() => {
      const applyTheme = () => {
          const isDark = settings.appearance === 'dark' || (settings.appearance === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches);

          if (isDark) {
              document.documentElement.classList.add('dark');
              document.querySelector('meta[name="theme-color"]')?.setAttribute('content', '#1c1917');
          } else {
              document.documentElement.classList.remove('dark');
              document.querySelector('meta[name="theme-color"]')?.setAttribute('content', '#fafaf9');
          }
      };
      applyTheme();
      const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
      const handler = () => {
          if (settings.appearance === 'system') applyTheme();
      };
      mediaQuery.addEventListener('change', handler);
      return () => mediaQuery.removeEventListener('change', handler);
  }, [settings.appearance]);

  useEffect(() => { 
      sounds.setEnabled(settings.sound); 
      sounds.setVibrationEnabled(settings.vibration);
      sounds.setProfile(selectedSoundPackId);
  }, [settings.sound, settings.vibration, selectedSoundPackId]);

  useEffect(() => {
    const timer = setTimeout(() => {
        setDirection(1);
        setScreen('difficulty');
    }, 1500);
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
     setPurchasedBackgrounds(Storage.getPurchasedBackgrounds());
     setSelectedBackgroundId(Storage.getSelectedBackground());
     setPurchasedNumberColors(Storage.getPurchasedNumberColors());
     setSelectedNumberColorId(Storage.getSelectedNumberColor());
     setPurchasedSoundPacks(Storage.getPurchasedSoundPacks());
     setSelectedSoundPackId(Storage.getSelectedSoundPack());
     setPurchasedSkills(Storage.getPurchasedSkills());
     setEnabledSkills(Storage.getEnabledSkills());
     setStarterPackPurchased(Storage.isStarterPackPurchased());
     setPoints(Storage.getPoints());
     setUnlockedPacks2(Storage.getUnlockedPacks2());
     setUnlockedPacks3(Storage.getUnlockedPacks3());
     setNextBonusClaimTime(Storage.getNextBonusClaimTime());
  }, [screen]);

  const navigate = (nextScreen: Screen, dir: 'forward' | 'back' | 'none' = 'forward') => {
      setDirection(dir === 'forward' ? 1 : dir === 'back' ? -1 : 0);
      setScreen(nextScreen);
      setPoints(Storage.getPoints());
  };

  const handleDifficultySelect = (diff: Difficulty) => {
    sounds.playClick();
    setSelectedDifficulty(diff);
    navigate('levels', 'forward');
  };

  const handleLevelBack = () => { sounds.playClick(); navigate('difficulty', 'back'); };
  const handleGameBack = () => { sounds.playClick(); navigate('levels', 'back'); };
  const handleReturnToMenu = () => { sounds.playClick(); navigate('difficulty', 'back'); };
  const handleStoreBack = () => { sounds.playClick(); navigate('difficulty', 'back'); };
  const handleDiamondShopBack = () => { sounds.playClick(); navigate('difficulty', 'back'); };
  const handleStatsBack = () => { sounds.playClick(); navigate('difficulty', 'back'); };

  const handleLevelSelect = (levelId: number) => {
    const progress = Storage.getLevelProgress(selectedDifficulty!, levelId);
    if (progress?.status === 'completed') {
        sounds.playClick();
        setReplayLevelId(levelId);
    } else {
        sounds.playLevelEnter();
        setSelectedLevel(levelId);
        navigate('game', 'forward');
    }
  };

  const confirmReplay = () => {
      sounds.playLevelEnter();
      if (selectedDifficulty && replayLevelId) {
          Storage.clearLevelProgress(selectedDifficulty, replayLevelId);
          setReplayLevelId(null);
          setSelectedLevel(replayLevelId);
          navigate('game', 'forward');
      }
  };

  const toggleSetting = (key: keyof AppSettings) => {
    sounds.playClick();
    const newSettings = { ...settings, [key]: !settings[key] };
    setSettings(newSettings);
    Storage.saveSettings(newSettings);
  };

  const handleToggleDifficultyVisibility = (diff: Difficulty) => {
      sounds.playTap();
      const currentHidden = settings.hiddenDifficulties || [];
      let newHidden: Difficulty[];

      if (currentHidden.includes(diff)) {
          newHidden = currentHidden.filter(d => d !== diff);
      } else {
          // Prevent hiding the last visible difficulty
          const allDiffs = Object.values(Difficulty);
          if (allDiffs.length - currentHidden.length <= 1) {
             // Maybe play error sound?
             return; 
          }
          newHidden = [...currentHidden, diff];
      }

      const newSettings = { ...settings, hiddenDifficulties: newHidden };
      setSettings(newSettings);
      Storage.saveSettings(newSettings);
  };

  const setAppearance = (val: 'system' | 'light' | 'dark') => {
      const newSettings = { ...settings, appearance: val };
      setSettings(newSettings);
      Storage.saveSettings(newSettings);
  };

  const resetProgress = async () => {
      sounds.playClick();
      if (confirm("Are you sure you want to reset all progress? This will clear data from Local Storage and Cloud Backup.")) {
          await Storage.resetAllData();
          window.location.reload();
      }
  };

  const handleSelectBackground = (id: string) => {
      sounds.playClick();
      Storage.selectBackground(id);
      setSelectedBackgroundId(id);
  };

  const handleSelectNumberColor = (id: string) => {
      sounds.playClick();
      Storage.selectNumberColor(id);
      setSelectedNumberColorId(id);
  };

  const handleSelectSoundPack = (id: string) => {
    Storage.selectSoundPack(id);
    setSelectedSoundPackId(id);
  };

  const handleToggleSkill = (id: string) => {
    const next = Storage.toggleSkillEnabled(id);
    setEnabledSkills([...next]);
  };

  // Simplified Earn Points Handler (No Fly-In)
  const handleEarnPoints = (amount: number) => {
    const newTotal = Storage.addPoints(amount);
    setPoints(newTotal);
  };

  const handleClaimBonus = (e: React.MouseEvent) => {
    const now = Date.now();
    if (now < nextBonusClaimTime) return;
    sounds.playWin();

    // Set next claim time to next midnight (00:00:00)
    const nextDate = new Date();
    nextDate.setDate(nextDate.getDate() + 1);
    nextDate.setHours(0, 0, 0, 0);
    const nextTime = nextDate.getTime();

    Storage.setNextBonusClaimTime(nextTime);
    setNextBonusClaimTime(nextTime);
    handleEarnPoints(10);
  };

  const initiatePurchase = (item: any, type: 'bg' | 'num' | 'skill' | 'sound') => {
      // Don't play the default 'pop' sound if we are buying a sound pack, 
      // as the preview of that sound pack will already be playing.
      if (type !== 'sound') {
          sounds.playPop();
      }
      setPurchaseCandidate({ ...item, type });
  };

  const confirmPurchase = () => {
      if (!purchaseCandidate) return;
      if (points >= purchaseCandidate.cost) {
          if (purchaseCandidate.type === 'bg') {
             if(Storage.purchaseBackground(purchaseCandidate.id, purchaseCandidate.cost)) {
                setPurchasedBackgrounds([...purchasedBackgrounds, purchaseCandidate.id]);
                handleSelectBackground(purchaseCandidate.id);
             }
          } else if (purchaseCandidate.type === 'num') {
             if(Storage.purchaseNumberColor(purchaseCandidate.id, purchaseCandidate.cost)) {
                setPurchasedNumberColors([...purchasedNumberColors, purchaseCandidate.id]);
                handleSelectNumberColor(purchaseCandidate.id);
             }
          } else if (purchaseCandidate.type === 'skill') {
             if(Storage.purchaseSkill(purchaseCandidate.id, purchaseCandidate.cost)) {
                setPurchasedSkills(Storage.getPurchasedSkills());
                setEnabledSkills(Storage.getEnabledSkills());
             }
          } else if (purchaseCandidate.type === 'sound') {
            if(Storage.purchaseSoundPack(purchaseCandidate.id, purchaseCandidate.cost)) {
               setPurchasedSoundPacks([...purchasedSoundPacks, purchaseCandidate.id]);
               handleSelectSoundPack(purchaseCandidate.id);
            }
          }
          setPoints(Storage.getPoints());
          setPurchaseCandidate(null);
      } else {
          setPurchaseCandidate(null);
          setShowNotEnoughPoints(true);
      }
  };

  const handleWatchAd = async () => {
        setShowNotEnoughPoints(false);
        setPurchaseCandidate(null);
        // Show the internal 'fake' ad overlay which provides rewards
        setIsWatchingAd(true);
  };

  const handleAdReward = () => {
      handleEarnPoints(25);
      setIsWatchingAd(false);
      sounds.playWin();
  };

  const handleNavigateToShop = () => {
      setShowNotEnoughPoints(false);
      navigate('diamondShop', 'forward');
  };

  const handleGoPlay = () => {
      setShowNotEnoughPoints(false);
      setPurchaseCandidate(null);
      if (screen === 'store') {
          navigate('difficulty', 'back');
      }
  };

  const handleBuyOffer = (offer: DiamondOffer) => {
      sounds.playClick();
      // Only check starter pack restriction
      if (offer.type === 'starter' && starterPackPurchased) return;
      if (offer.priceLabel === '') return;
      setPaymentOffer(offer);
  };

  const finalizeRealMoneyPurchase = () => {
      if (!paymentOffer) return;
      const offer = paymentOffer;

      handleEarnPoints(offer.diamonds);

      if (offer.type === 'starter') {
          Storage.setStarterPackPurchased();
          setStarterPackPurchased(true);
          Storage.purchaseSkill('skill-auto', 0);
          Storage.purchaseSkill('skill-scan', 0);
          Storage.purchaseSoundPack('snd-piano', 0);
      } else if (offer.type === 'support') {
          Storage.unlockPepino();
      }

      setPurchasedSkills(Storage.getPurchasedSkills());
      setEnabledSkills(Storage.getEnabledSkills());
      setPurchasedNumberColors(Storage.getPurchasedNumberColors());
      setPurchasedBackgrounds(Storage.getPurchasedBackgrounds());
      setPurchasedSoundPacks(Storage.getPurchasedSoundPacks());
      setPaymentOffer(null);
  };

  const handleUnlockPack2 = () => {
      if (!selectedDifficulty) return;
      const cost = getPackCost(selectedDifficulty, 2);
      if (points >= cost) {
          sounds.playPop();
          if (Storage.unlockPack2(selectedDifficulty, cost)) {
              setPoints(Storage.getPoints());
              setUnlockedPacks2(Storage.getUnlockedPacks2());
              sounds.playWin();
          }
      } else {
          sounds.playClick();
          setShowNotEnoughPoints(true);
      }
  };

  const handleUnlockPack3 = () => {
      if (!selectedDifficulty) return;
      const cost = getPackCost(selectedDifficulty, 3);
      if (points >= cost) {
          sounds.playPop();
          if (Storage.unlockPack3(selectedDifficulty, cost)) {
              setPoints(Storage.getPoints());
              setUnlockedPacks3(Storage.getUnlockedPacks3());
              sounds.playWin();
          }
      } else {
          sounds.playClick();
          setShowNotEnoughPoints(true);
      }
  };

  let activeBackgroundClass = "bg-paper dark:bg-stone-900"; 

  if (selectedBackgroundId) {
      const bg = ALL_BACKGROUNDS.find(b => b.id === selectedBackgroundId);
      if (bg) {
          activeBackgroundClass = bg.class;
      }
  }

  const numberColorClass = NUMBER_COLORS.find(n => n.id === selectedNumberColorId)?.class || 'text-blue-600';
  const isGradient = activeBackgroundClass.includes('bg-gradient');
  let overlayOpacity = '0';
  if (isGradient) {
      if (screen === 'game') {
          overlayOpacity = 'calc(var(--overlay-opacity) * 1.6)';
      } else {
          overlayOpacity = 'var(--overlay-opacity)';
      }
  } else if (screen === 'game') {
      overlayOpacity = 'calc(var(--overlay-opacity) * 0.6)';
  }

  // Animation Variants for "Slide" Transition
  // Using 100% width slide to prevent cuts and ensure screens move completely off-view
  const variants: Variants = {
    initial: (dir: number) => ({
      x: dir > 0 ? '100%' : (dir < 0 ? '-100%' : 0),
      opacity: 0
    }),
    animate: {
      x: 0,
      opacity: 1,
      transition: { 
          type: "spring", 
          stiffness: 260, 
          damping: 25
      }
    },
    exit: (dir: number) => ({
      x: dir > 0 ? '-100%' : '100%',
      opacity: 0,
      transition: { 
          type: "spring", 
          stiffness: 260, 
          damping: 25
      }
    })
  };

  return (
      <>
          {/* Main App Wrapper: Fixed, Full Viewport, No Overflow */}
          <div className="fixed inset-0 z-0 w-full h-full overflow-hidden select-none touch-none">

              {/* Background Layer (Persistent) */}
              <div 
                className={`absolute inset-0 z-0 transition-all ease-in-out duration-500 ${activeBackgroundClass}`} 
                style={{ width: '100%', height: '100%' }}
              />
              <div 
                className="absolute inset-0 z-[1] bg-black pointer-events-none transition-opacity duration-500" 
                style={{ opacity: overlayOpacity }} 
              />

              {/* Diamond Shop Background (Behind Safe Area Wrapper) */}
              {screen === 'diamondShop' && <DiamondBackground />}

              {/* Content Wrapper with Safe Areas */}
              {/* This inner container handles safe area padding to prevent content from being covered by notch/home bar */}
              <div 
                 className="relative z-10 w-full h-full flex flex-col pt-safe pb-safe"
              >
                <div className="flex-1 relative w-full h-full overflow-hidden">
                    <AnimatePresence custom={direction} initial={false}>
                        <motion.div
                            key={screen}
                            custom={direction}
                            variants={variants}
                            initial="initial"
                            animate="animate"
                            exit="exit"
                            className="absolute inset-0 w-full h-full flex flex-col items-center justify-center font-sans text-t-primary overflow-hidden bg-transparent"
                            style={{ pointerEvents: 'auto' }}
                        >
                            {screen === 'splash' && <SplashScreen />}

                            {screen === 'difficulty' && (
                                <DifficultyScreen 
                                    points={points}
                                    onDifficultySelect={handleDifficultySelect}
                                    onOpenSettings={() => setShowSettings(true)}
                                    onOpenStore={() => navigate('store', 'forward')}
                                    onOpenDiamondShop={() => navigate('diamondShop', 'forward')}
                                    onClaimBonus={handleClaimBonus}
                                    onOpenStats={() => navigate('stats', 'forward')}
                                    nextBonusClaimTime={nextBonusClaimTime}
                                    hiddenDifficulties={settings.hiddenDifficulties}
                                />
                            )}

                            {screen === 'diamondShop' && (
                                <DiamondShopScreen 
                                    points={points}
                                    onBack={handleDiamondShopBack}
                                    onWatchAd={handleWatchAd}
                                    onBuyOffer={handleBuyOffer}
                                    onEarnPoints={handleEarnPoints}
                                    starterPackPurchased={starterPackPurchased}
                                />
                            )}

                            {screen === 'stats' && (
                                <StatsScreen 
                                    onBack={handleStatsBack}
                                    onEarnPoints={handleEarnPoints}
                                    points={points}
                                />
                            )}

                            {screen === 'levels' && selectedDifficulty && (
                                <LevelsScreen 
                                    difficulty={selectedDifficulty}
                                    points={points}
                                    unlockedPacks2={unlockedPacks2}
                                    unlockedPacks3={unlockedPacks3}
                                    onBack={handleLevelBack}
                                    onLevelSelect={handleLevelSelect}
                                    onOpenSettings={() => setShowSettings(true)}
                                    onUnlockPack2={handleUnlockPack2}
                                    onUnlockPack3={handleUnlockPack3}
                                />
                            )}

                            {screen === 'store' && (
                                <StoreScreen 
                                    points={points}
                                    onBack={handleStoreBack}
                                    purchasedSkills={purchasedSkills}
                                    enabledSkills={enabledSkills}
                                    purchasedBackgrounds={purchasedBackgrounds}
                                    purchasedNumberColors={purchasedNumberColors}
                                    purchasedSoundPacks={purchasedSoundPacks}
                                    selectedBackgroundId={selectedBackgroundId}
                                    selectedNumberColorId={selectedNumberColorId}
                                    selectedSoundPackId={selectedSoundPackId}
                                    onPurchase={initiatePurchase}
                                    onSelectBackground={handleSelectBackground}
                                    onSelectNumberColor={handleSelectNumberColor}
                                    onSelectSoundPack={handleSelectSoundPack}
                                    onToggleSkill={handleToggleSkill}
                                />
                            )}

                            {screen === 'game' && selectedDifficulty && selectedLevel && (
                                <SudokuGame
                                    difficulty={selectedDifficulty}
                                    levelId={selectedLevel}
                                    onBack={handleGameBack}
                                    onReturnToMenu={handleReturnToMenu}
                                    onComplete={() => {
                                        setPoints(Storage.getPoints());
                                    }}
                                    onSettingsOpen={() => setShowSettings(true)}
                                    settings={settings}
                                    onEarnPoints={handleEarnPoints}
                                    currentPoints={points}
                                    isSettingsOpen={showSettings}
                                    backgroundClass={activeBackgroundClass}
                                    numberColor={numberColorClass}
                                    purchasedSkills={enabledSkills} // Pass only enabled skills to game
                                />
                            )}
                        </motion.div>
                    </AnimatePresence>
                </div>

                {/* Modals & Overlays (Outside AnimatePresence to float on top) */}
                {showSettings && (
                    <SettingsModal 
                        settings={settings} 
                        onToggle={toggleSetting} 
                        onToggleDifficulty={handleToggleDifficultyVisibility}
                        onSetAppearance={setAppearance}
                        onReset={resetProgress}
                        onClose={() => setShowSettings(false)} 
                    />
                )}
                {replayLevelId !== null && selectedDifficulty && (
                    <ReplayModal 
                        levelId={replayLevelId}
                        onConfirm={confirmReplay}
                        onCancel={() => setReplayLevelId(null)}
                    />
                )}
                {purchaseCandidate && (
                    <PurchaseModal 
                        item={purchaseCandidate} 
                        onConfirm={confirmPurchase} 
                        onCancel={() => setPurchaseCandidate(null)} 
                    />
                )}
                {paymentOffer && (
                    <PaymentModal
                        offer={paymentOffer}
                        onComplete={finalizeRealMoneyPurchase}
                        onCancel={() => setPaymentOffer(null)}
                    />
                )}
                {showNotEnoughPoints && (
                    <NotEnoughPointsModal 
                        onClose={() => setShowNotEnoughPoints(false)} 
                        onGetMore={handleNavigateToShop} 
                        onGoPlay={handleGoPlay} 
                    />
                )}
                {/* 
                   Ad Overlay: Since native AdMob is removed, we always trigger this
                   fake overlay when isWatchingAd is true.
                */}
                {isWatchingAd && <AdOverlay onComplete={handleAdReward} />}
              </div>
          </div>
      </>
  );
}

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Difficulty, LevelProgress } from '../../types';
import { Storage } from '../../utils/storage';
import { Icons } from '../ui/Icons';
import { UnlockCard } from '../ui/UnlockCard';
import { getPackCost, formatTimeShort } from '../../utils/constants';
import { AnimatedNumber } from '../ui/AnimatedNumber';
import { sounds } from '../../utils/sound';

// --- OPTIMIZED LEVEL BUTTON COMPONENT ---
interface LevelButtonProps {
    levelId: number;
    status?: 'locked' | 'not-started' | 'in-progress' | 'completed';
    bestTime?: number;
    isGlobalBest: boolean;
    onSelect: (levelId: number) => void;
}

const LevelButton = React.memo(({ levelId, status, bestTime, isGlobalBest, onSelect }: LevelButtonProps) => {
    const isSolved = bestTime !== undefined || status === 'completed';
    const isInProgress = status === 'in-progress';

    let buttonClass = 'aspect-square rounded-xl relative transition-all active:scale-90 shadow-sm ';

    if (isSolved) {
        buttonClass += 'bg-t-surface-sec text-t-secondary ring-1 ring-inset ring-stone-900/5 ';
        if (isInProgress) {
            buttonClass += '!ring-2 !ring-blue-400 !text-t-primary ';
        }
    } else if (isInProgress) {
        buttonClass += 'bg-t-surface ring-2 ring-blue-400 shadow-md text-t-primary ';
    } else {
        buttonClass += 'bg-t-surface hover:shadow-md text-t-primary ';
    }

    return (
        <button onClick={() => onSelect(levelId)} className={buttonClass}>
            <div className="absolute inset-0 flex items-center justify-center"><span className="font-bold text-2xl leading-none">{levelId}</span></div>
            {bestTime ? (
                isGlobalBest ? (
                    <>
                        <div className="absolute top-1.5 inset-x-0 flex justify-center">
                            <span className="text-[8px] font-bold text-amber-500 tracking-widest opacity-90 animate-pulse">BEST</span>
                        </div>
                        <div className="absolute bottom-1.5 inset-x-0 flex justify-center">
                            <span className="text-[10px] text-amber-500 font-bold tracking-tight block leading-none animate-pulse">{formatTimeShort(bestTime)}</span>
                        </div>
                    </>
                ) : (
                    <div className="absolute bottom-1.5 inset-x-0 text-center">
                        <span className={`text-[10px] font-bold tracking-tight block ${isInProgress ? 'text-t-primary' : 'text-t-secondary'}`}>{formatTimeShort(bestTime)}</span>
                    </div>
                )
            ) : null}
        </button>
    );
});

interface LevelsScreenProps {
    difficulty: Difficulty;
    points: number;
    unlockedPacks2: string[];
    unlockedPacks3: string[];
    onBack: () => void;
    onLevelSelect: (levelId: number) => void;
    onOpenSettings: () => void;
    onUnlockPack2: () => void;
    onUnlockPack3: () => void;
}

export const LevelsScreen: React.FC<LevelsScreenProps> = ({ 
    difficulty, 
    points,
    unlockedPacks2, 
    unlockedPacks3, 
    onBack, 
    onLevelSelect, 
    onOpenSettings,
    onUnlockPack2,
    onUnlockPack3
}) => {
    // --- BATCH DATA LOADING ---
    const [progressMap] = useState(() => Storage.getStoredData().progress);

    // --- TAB STATE ---
    const [activeTab, setActiveTab] = useState<1 | 2 | 3>(1);
    const scrollContainerRef = useRef<HTMLDivElement>(null);

    // Reset scroll on tab change
    useEffect(() => {
        if (scrollContainerRef.current) {
            scrollContainerRef.current.scrollTop = 0;
        }
    }, [activeTab]);

    // --- CALCULATE STATS ---
    const { globalBest, completedRange1, completedRange2 } = useMemo(() => {
        let best = Infinity;
        let c1 = 0;
        let c2 = 0;

        for (let i = 1; i <= 300; i++) {
            const key = `${difficulty}-${i}`;
            const p = progressMap[key];
            if (p && (p.status === 'completed' || p.bestTime !== undefined)) {
                if (i <= 100) c1++;
                else if (i <= 200) c2++;

                if (p.bestTime !== undefined && p.bestTime < best) {
                    best = p.bestTime;
                }
            }
        }

        return { 
            globalBest: best === Infinity ? undefined : best, 
            completedRange1: c1, 
            completedRange2: c2 
        };
    }, [progressMap, difficulty]);

    const isPack2Unlocked = unlockedPacks2.includes(difficulty);
    const isPack3Unlocked = unlockedPacks3.includes(difficulty);

    // Determine Visible Tabs: Pack 1 & 2 always visible. Pack 3 only if Pack 2 unlocked.
    const visibleTabs = [1, 2];
    if (isPack2Unlocked) visibleTabs.push(3);

    const handleTabChange = (tab: 1 | 2 | 3) => {
        sounds.playClick();
        setActiveTab(tab);
    };

    const renderContent = () => {
        if (activeTab === 1) {
            const levels = Array.from({ length: 100 }, (_, i) => i + 1);
            return (
                <div className="flex flex-col items-center w-full max-w-md">
                    <div className="w-full grid grid-cols-5 gap-3 pt-2 pb-6">
                        {levels.map(lvl => {
                            const key = `${difficulty}-${lvl}`;
                            const progress = progressMap[key];
                            return (
                                <LevelButton 
                                    key={lvl}
                                    levelId={lvl}
                                    status={progress?.status}
                                    bestTime={progress?.bestTime}
                                    isGlobalBest={globalBest !== undefined && progress?.bestTime === globalBest}
                                    onSelect={onLevelSelect}
                                />
                            );
                        })}
                    </div>
                </div>
            );
        }

        if (activeTab === 2) {
            if (!isPack2Unlocked) {
                return (
                    <div className="flex-1 flex flex-col items-center justify-center w-full max-w-md pb-20 animate-fade-in">
                        <UnlockCard 
                            startLevel={101}
                            endLevel={200}
                            completedCount={completedRange1}
                            totalBaseLevels={100}
                            cost={getPackCost(difficulty, 2)}
                            onUnlock={onUnlockPack2}
                        />
                    </div>
                );
            }
            const levels = Array.from({ length: 100 }, (_, i) => i + 101);
            return (
                <div className="flex flex-col items-center w-full max-w-md">
                    <div className="w-full grid grid-cols-5 gap-3 pt-2 pb-6 animate-fade-in">
                        {levels.map(lvl => {
                            const key = `${difficulty}-${lvl}`;
                            const progress = progressMap[key];
                            return (
                                <LevelButton 
                                    key={lvl}
                                    levelId={lvl}
                                    status={progress?.status}
                                    bestTime={progress?.bestTime}
                                    isGlobalBest={globalBest !== undefined && progress?.bestTime === globalBest}
                                    onSelect={onLevelSelect}
                                />
                            );
                        })}
                    </div>
                </div>
            );
        }

        if (activeTab === 3) {
            if (!isPack3Unlocked) {
                return (
                    <div className="flex-1 flex flex-col items-center justify-center w-full max-w-md pb-20 animate-fade-in">
                        <UnlockCard 
                            startLevel={201}
                            endLevel={300}
                            completedCount={completedRange2}
                            totalBaseLevels={100}
                            cost={getPackCost(difficulty, 3)}
                            onUnlock={onUnlockPack3}
                        />
                    </div>
                );
            }
            const levels = Array.from({ length: 100 }, (_, i) => i + 201);
            return (
                <div className="flex flex-col items-center w-full max-w-md animate-fade-in">
                    <div className="w-full grid grid-cols-5 gap-3 pt-2 pb-6">
                        {levels.map(lvl => {
                            const key = `${difficulty}-${lvl}`;
                            const progress = progressMap[key];
                            return (
                                <LevelButton 
                                    key={lvl}
                                    levelId={lvl}
                                    status={progress?.status}
                                    bestTime={progress?.bestTime}
                                    isGlobalBest={globalBest !== undefined && progress?.bestTime === globalBest}
                                    onSelect={onLevelSelect}
                                />
                            );
                        })}
                    </div>
                </div>
            );
        }
    };

    return (
        <div className="flex-1 w-full flex flex-col items-center overflow-hidden">
            <div className="w-full max-w-md flex flex-col items-center px-6 pt-4 shrink-0 z-20 gap-4">

                {/* Header Row */}
                <div className="w-full flex items-center justify-between relative">
                    <button onClick={onBack} className="p-2 rounded-full hover:bg-stone-200/50 transition -ml-2 text-t-icon relative z-30">
                        <Icons.Back className="w-6 h-6 text-t-icon" />
                    </button>

                    <div className="flex flex-col items-center absolute left-0 right-0 pointer-events-none z-20">
                        <h1 className="text-xl font-bold leading-none">{difficulty}</h1>
                        <p className="text-xs text-t-secondary uppercase tracking-widest mt-1">Select Level</p>
                        {globalBest !== undefined && (
                            <div className="flex flex-col items-center animate-fade-in mt-1">
                                <span className="text-[10px] font-bold text-amber-500 tracking-widest uppercase mb-px opacity-90">Best: {formatTimeShort(globalBest)}</span>
                            </div>
                        )}
                    </div>

                    <div className="flex items-center gap-1.5 bg-t-surface px-3 py-1.5 rounded-full shadow-sm relative z-30">
                        <AnimatedNumber value={points} className="text-sm font-semibold text-t-primary tabular-nums leading-none pt-0.5" />
                        <div className="text-blue-500"><Icons.Diamond className="w-3.5 h-3.5 fill-current" /></div>
                    </div>
                </div>

                {/* Tab Navigation (Scrollable Pills) */}
                <div className="w-full overflow-x-auto hide-scrollbar touch-pan-x pb-2 pt-1 -mx-6 px-6">
                    <div className="flex gap-3 min-w-min mx-auto md:mx-0">
                        {visibleTabs.map((tabNum) => {
                            const isActive = activeTab === tabNum;
                            // Only confirm lock if it's strictly the next unavailable one
                            const isLocked = (tabNum === 2 && !isPack2Unlocked) || (tabNum === 3 && !isPack3Unlocked);

                            return (
                                <button
                                    key={tabNum}
                                    onClick={() => handleTabChange(tabNum as 1|2|3)}
                                    className={`
                                        px-6 py-2.5 rounded-full text-xs font-bold transition-all flex items-center justify-center gap-2 whitespace-nowrap shadow-sm border
                                        ${isActive 
                                            ? 'bg-stone-800 border-stone-800 text-white dark:bg-stone-100 dark:border-stone-100 dark:text-stone-900 scale-105' 
                                            : 'bg-white border-stone-200 text-stone-500 dark:bg-stone-800 dark:border-stone-700 dark:text-stone-400 hover:border-stone-300 dark:hover:border-stone-600'
                                        }
                                    `}
                                >
                                    {isLocked && <Icons.Lock className="w-3 h-3 opacity-60" />}
                                    <span>Pack {tabNum}</span>
                                </button>
                            );
                        })}
                    </div>
                </div>
            </div>

            {/* Scrollable Content Area */}
            <div 
                ref={scrollContainerRef}
                className="flex-1 w-full overflow-y-auto px-6 pb-6 hide-scrollbar flex flex-col items-center relative"
            >
                {renderContent()}
                <div className="h-safe-bottom w-full shrink-0" />
            </div>
        </div>
    );
};

import React, { useRef, useState, useEffect } from 'react';
import { Icons } from './Icons';

interface UnlockCardProps {
    startLevel: number;
    endLevel: number;
    completedCount: number;
    totalBaseLevels: number;
    cost: number;
    onUnlock: () => void;
}

export const UnlockCard: React.FC<UnlockCardProps> = ({ startLevel, endLevel, completedCount, totalBaseLevels, cost, onUnlock }) => {
    const cardRef = useRef<HTMLDivElement>(null);
    const [isVisible, setIsVisible] = useState(false);
    const [animatedPercent, setAnimatedPercent] = useState(0);
    const [showUnlockUI, setShowUnlockUI] = useState(false);

    // Calculate percentage (capped at 100%)
    const rawPercent = Math.min(100, Math.floor((completedCount / totalBaseLevels) * 100));

    useEffect(() => {
        const observer = new IntersectionObserver(
            ([entry]) => {
                if (entry.isIntersecting) {
                    setIsVisible(true);
                } else {
                    setIsVisible(false);
                    setAnimatedPercent(0); // Reset for replay
                    setShowUnlockUI(false); // Reset UI state
                }
            },
            { threshold: 0.2 } // Trigger when 20% visible
        );

        if (cardRef.current) {
            observer.observe(cardRef.current);
        }

        return () => observer.disconnect();
    }, []);

    useEffect(() => {
        if (isVisible) {
            // Animate progress
            const duration = 2500; // Slower duration
            const startTime = performance.now();

            const animate = (time: number) => {
                const elapsed = time - startTime;
                const progress = Math.min(elapsed / duration, 1);
                const ease = progress; // Linear easing

                setAnimatedPercent(Math.floor(rawPercent * ease));

                if (progress < 1) {
                    requestAnimationFrame(animate);
                } else {
                    setAnimatedPercent(rawPercent);
                    if (rawPercent === 100) {
                        // Wait a moment after hitting 100% before showing the unlock button
                        setTimeout(() => {
                            setShowUnlockUI(true);
                        }, 500);
                    }
                }
            };
            requestAnimationFrame(animate);
        }
    }, [isVisible, rawPercent]);

    const handleUnlockClick = () => {
        if (!showUnlockUI) return;
        onUnlock();
    };

    return (
        <div ref={cardRef} className="w-full max-w-md mt-6 px-1">
            <button 
                onClick={handleUnlockClick}
                disabled={!showUnlockUI}
                className={`w-full h-32 rounded-[1.5rem] relative overflow-hidden transition-all duration-500 ease-out group ${
                    showUnlockUI 
                        ? 'bg-gradient-to-b from-white to-blue-50/50 dark:from-stone-800 dark:to-stone-900 shadow-lg active:scale-[0.98] cursor-pointer' 
                        : 'bg-stone-200 dark:bg-stone-800/80 cursor-default'
                }`}
            >
                {/* Background Decor for Unlock State */}
                {showUnlockUI && (
                    <div className="absolute inset-0 opacity-100 pointer-events-none">
                        <div className="absolute -top-12 -right-12 w-32 h-32 bg-blue-400/10 rounded-full blur-2xl"></div>
                        <div className="absolute -bottom-12 -left-12 w-32 h-32 bg-indigo-400/10 rounded-full blur-2xl"></div>
                    </div>
                )}

                {/* Content Container */}
                <div className="absolute inset-0 flex items-center justify-center px-6">
                    {showUnlockUI ? (
                        <div className="flex flex-row items-center justify-between w-full animate-fade-in relative z-10 gap-2">

                             {/* Left Side: Info & CTA */}
                             <div className="flex flex-col items-start gap-1.5">
                                 {/* Header Pill */}
                                 <div className="flex items-center gap-1.5 px-2.5 py-1 bg-white dark:bg-stone-800 rounded-full shadow-sm">
                                    <Icons.LockOpen className="w-3 h-3 text-blue-500" />
                                    <span className="text-[10px] font-bold text-stone-500 dark:text-stone-400 uppercase tracking-widest pt-0.5">
                                        Levels {startLevel}-{endLevel}
                                    </span>
                                 </div>
                                 {/* Flashing CTA */}
                                 <span className="text-[10px] font-bold text-blue-500 uppercase tracking-widest pl-1 animate-pulse ml-0.5">
                                     Tap to Unlock
                                 </span>
                             </div>

                             {/* Right Side: Price */}
                             <div className="flex items-center gap-2">
                                <span className="text-5xl font-bold text-stone-900 dark:text-white leading-none">
                                    {cost}
                                </span>
                                <Icons.Diamond className="w-8 h-8 text-blue-500 fill-current drop-shadow-sm" />
                             </div>
                        </div>
                    ) : (
                        <div className="flex flex-row items-center justify-between w-full gap-4">
                            {/* Left Side: Locked Status Box */}
                            <div className="w-16 h-16 rounded-2xl bg-stone-300/50 dark:bg-stone-700/50 flex flex-col items-center justify-center shrink-0 border border-stone-300/30 dark:border-stone-600/30 shadow-inner">
                                <Icons.Lock className="w-5 h-5 text-stone-500 dark:text-stone-400 mb-1" />
                                <span className="text-[10px] font-bold text-stone-500 dark:text-stone-400 uppercase tracking-widest opacity-80 leading-none">
                                    {animatedPercent}%
                                </span>
                            </div>

                            {/* Right Side: Progress Details */}
                            <div className="flex-1 flex flex-col justify-center gap-2.5">
                                <div className="flex justify-between items-end px-0.5">
                                    <span className="text-xs font-bold text-stone-600 dark:text-stone-300 uppercase tracking-wide leading-none">
                                        Locked
                                    </span>
                                    <span className="text-[10px] font-medium text-stone-400 dark:text-stone-500 leading-none">
                                        {completedCount}/{totalBaseLevels} Levels
                                    </span>
                                </div>

                                {/* Modern Progress Bar */}
                                <div className="w-full h-3 bg-stone-300/50 dark:bg-stone-700/50 rounded-full overflow-hidden p-[2px] shadow-sm">
                                    <div 
                                        className="h-full bg-stone-500 dark:bg-stone-400 rounded-full shadow-sm transition-all duration-300 ease-out min-w-[6px] relative overflow-hidden" 
                                        style={{ width: `${animatedPercent}%` }}
                                    >
                                        <div className="absolute inset-0 opacity-10 bg-[linear-gradient(45deg,rgba(255,255,255,0.5)_25%,transparent_25%,transparent_50%,rgba(255,255,255,0.5)_50%,rgba(255,255,255,0.5)_75%,transparent_75%,transparent)] bg-[length:8px_8px]" />
                                    </div>
                                </div>

                                <p className="text-[10px] font-medium text-stone-400 dark:text-stone-500 leading-tight px-0.5">
                                    Complete previous pack to unlock.
                                </p>
                            </div>
                        </div>
                    )}
                </div>
            </button>
        </div>
    );
};

import { Haptics, ImpactStyle, NotificationType } from '@capacitor/haptics';

interface SoundProfile {
    id: string;
    type: 'sine' | 'square' | 'triangle' | 'sawtooth' | 'noise';
    uiClickFreq: number;
    uiTapFreq: number;
    numberFreqs: number[];
    popFreq: number;
    duration: number; // Base duration in seconds
    volumeScale: number;
    pitchDrop?: boolean;
    noiseFilterFreq?: number; // Center freq for noise bands
    tapFreqs?: number[]; // Frequencies for random variation on tap
}

const PROFILES: Record<string, SoundProfile> = {
    'snd-zen': {
        id: 'snd-zen',
        type: 'sine',
        uiClickFreq: 800, 
        uiTapFreq: 800,
        numberFreqs: Array(9).fill(600),
        popFreq: 400,
        duration: 0.035, 
        volumeScale: 1.0, 
        pitchDrop: true
    },
    'snd-paper': {
        id: 'snd-paper',
        type: 'noise', 
        uiClickFreq: 1200, 
        uiTapFreq: 1000,
        numberFreqs: Array(9).fill(1000), 
        popFreq: 800,
        duration: 0.05,
        volumeScale: 0.9,
        noiseFilterFreq: 800
    },
    'snd-wood': {
        id: 'snd-wood',
        type: 'sine', // Carrier is Sine, but we use FM synthesis
        uiClickFreq: 330, // E4 - Solid knock
        uiTapFreq: 392,   // G4
        tapFreqs: [330, 349, 392, 440], // Random log hits
        // E Minor Pentatonic (Forest/Mystic): E4, G4, A4, B4, D5, E5, G5, A5, B5
        numberFreqs: [329.63, 392.00, 440.00, 493.88, 587.33, 659.25, 783.99, 880.00, 987.77],
        popFreq: 164.8, // E3 (Deep Thud)
        duration: 0.15, 
        volumeScale: 1.4, // FM sounds can be quieter
        pitchDrop: false 
    },
    'snd-water': {
        id: 'snd-water',
        type: 'sine',
        uiClickFreq: 600,
        uiTapFreq: 700,
        // Whole Tone Scale (Dreamy/Fluid): C5, D5, E5, F#5, G#5, A#5, C6, D6, E6
        numberFreqs: [523.25, 587.33, 659.25, 739.99, 830.61, 932.33, 1046.50, 1174.66, 1318.51],
        popFreq: 400,
        duration: 0.1, 
        volumeScale: 0.9,
        pitchDrop: false // We use upward ramp
    },
    'snd-piano': {
        id: 'snd-piano',
        type: 'triangle', 
        uiClickFreq: 1046, // Fallback freq
        uiTapFreq: 523, // C5
        tapFreqs: [523.25, 587.33, 659.25, 783.99, 880.00], // C Major Pentatonic
        // Pentatonic Major Scale: C4, D4, E4, G4, A4, C5, D5, E5, G5
        numberFreqs: [261.63, 293.66, 329.63, 392.00, 440.00, 523.25, 587.33, 659.25, 783.99],
        popFreq: 196, // G3
        duration: 1.5, // Long sustained tail
        volumeScale: 0.6,
        pitchDrop: false
    }
};

class SoundController {
    private ctx: AudioContext | null = null;
    private soundEnabled: boolean = true;
    private vibrationEnabled: boolean = true;
    private activeProfile: SoundProfile = PROFILES['snd-zen'];
    private lastTickTime: number = 0;

    setEnabled(enabled: boolean) {
        this.soundEnabled = enabled;
    }

    setVibrationEnabled(enabled: boolean) {
        this.vibrationEnabled = enabled;
    }

    setProfile(profileId: string) {
        // Migrations
        if (profileId === 'snd-glass') profileId = 'snd-water';
        if (profileId === 'snd-celeste') profileId = 'snd-piano';

        if (PROFILES[profileId]) {
            this.activeProfile = PROFILES[profileId];
        } else {
            this.activeProfile = PROFILES['snd-zen'];
        }
    }

    private getCtx() {
        if (!this.ctx) {
            const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
            this.ctx = new AudioContext();
        }
        if (this.ctx.state === 'suspended') {
            this.ctx.resume();
        }
        return this.ctx;
    }

    private playNoiseBurst(centerFreq: number, duration: number, volume: number) {
        if (!this.soundEnabled) return;
        const ctx = this.getCtx();

        const bufferSize = ctx.sampleRate * duration;
        const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
        const data = buffer.getChannelData(0);
        for (let i = 0; i < bufferSize; i++) {
            data[i] = (Math.random() * 2 - 1);
        }

        const noise = ctx.createBufferSource();
        noise.buffer = buffer;

        const filter = ctx.createBiquadFilter();
        filter.type = 'bandpass';
        filter.Q.value = 0.7; 
        filter.frequency.setValueAtTime(centerFreq, ctx.currentTime);
        filter.frequency.exponentialRampToValueAtTime(centerFreq * 0.6, ctx.currentTime + duration);

        const gain = ctx.createGain();
        gain.gain.setValueAtTime(0, ctx.currentTime);
        gain.gain.linearRampToValueAtTime(volume, ctx.currentTime + 0.01);
        gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + duration);

        noise.connect(filter);
        filter.connect(gain);
        gain.connect(ctx.destination);

        noise.start();
        noise.stop(ctx.currentTime + duration + 0.1);
    }

    private playTone(
        freq: number, 
        duration: number, 
        volume: number, 
        type?: 'sine' | 'square' | 'triangle' | 'sawtooth',
        volumeScaleOverride?: number,
        disablePitchDrop: boolean = false,
        profileOverride?: SoundProfile
    ) {
        if (!this.soundEnabled) return;

        const profile = profileOverride || this.activeProfile;

        // Paper handling
        if (profile.id === 'snd-paper') {
            this.playNoiseBurst(profile.noiseFilterFreq || 800, duration, volume * profile.volumeScale);
            return;
        }

        const ctx = this.getCtx();
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();

        // --- SYNTHESIS LOGIC ---

        if (profile.id === 'snd-wood') {
             // Forest/Log Synthesis (FM)
             // Carrier: Sine
             // Modulator: Sine (Ratio 2:1 for hollow, woody sound)
             osc.type = 'sine';

             const mod = ctx.createOscillator();
             const modGain = ctx.createGain();

             mod.type = 'sine';
             mod.frequency.setValueAtTime(freq * 2.0, ctx.currentTime);

             // Mod Index Envelope (The "Thwack")
             // High modulation at start (complex tone), fast decay to pure sine (resonance)
             const modDepth = freq * 0.8; 
             modGain.gain.setValueAtTime(modDepth, ctx.currentTime);
             modGain.gain.exponentialRampToValueAtTime(1, ctx.currentTime + 0.05);

             mod.connect(modGain);
             modGain.connect(osc.frequency);

             mod.start();
             mod.stop(ctx.currentTime + duration + 0.1);

             osc.connect(gain);

        } else if (profile.id === 'snd-piano') {
            // Piano Synthesis (Filtered Triangle)
            osc.type = 'triangle';
            const filter = ctx.createBiquadFilter();
            filter.type = 'lowpass';
            filter.Q.value = 0.5; 
            filter.frequency.setValueAtTime(Math.min(freq * 6, 8000), ctx.currentTime); 
            filter.frequency.exponentialRampToValueAtTime(freq * 1.5, ctx.currentTime + 0.3);
            osc.connect(filter);
            filter.connect(gain);

        } else {
            // Standard (Zen, Water)
            osc.type = type || (profile.type as any);
            osc.connect(gain);
        }

        // --- PITCH ENVELOPES ---

        if (profile.id === 'snd-water') {
            // Water Bubble Physics: Pitch Ramps UP ("Bloop")
            // Start lower, slide up quickly to target freq
            osc.frequency.setValueAtTime(freq * 0.5, ctx.currentTime);
            osc.frequency.linearRampToValueAtTime(freq, ctx.currentTime + 0.04);
            // Slight overshoot for bubble pop effect?
            osc.frequency.linearRampToValueAtTime(freq * 1.1, ctx.currentTime + duration);

        } else if (profile.id === 'snd-wood') {
             // Wood stays relatively constant pitch (FM handles the transient)
             osc.frequency.setValueAtTime(freq, ctx.currentTime);
        } else if (profile.pitchDrop && !disablePitchDrop) {
            // Zen/Standard Drop
            osc.frequency.setValueAtTime(freq, ctx.currentTime);
            const dropTarget = Math.max(20, freq * 0.1); 
            osc.frequency.exponentialRampToValueAtTime(dropTarget, ctx.currentTime + duration);
        } else {
            osc.frequency.setValueAtTime(freq, ctx.currentTime);
        }

        const scale = volumeScaleOverride !== undefined ? volumeScaleOverride : profile.volumeScale;
        const vol = volume * scale;

        // --- AMPLITUDE ENVELOPES ---

        gain.gain.setValueAtTime(0, ctx.currentTime);

        if (profile.id === 'snd-piano') {
             gain.gain.linearRampToValueAtTime(vol, ctx.currentTime + 0.015);
             gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + duration);
        } else if (profile.id === 'snd-wood') {
             // Perussive: Instant attack, fast exponential decay
             gain.gain.setValueAtTime(vol, ctx.currentTime);
             gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + duration);
        } else if (profile.id === 'snd-water') {
             // Bubble: Softer attack, quick decay
             gain.gain.linearRampToValueAtTime(vol, ctx.currentTime + 0.02);
             gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + duration);
        } else {
             // Zen
             gain.gain.linearRampToValueAtTime(vol, ctx.currentTime + 0.002);
             gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + duration);
        }

        gain.connect(ctx.destination);

        osc.start();
        osc.stop(ctx.currentTime + duration + 0.2); 
    }

    playClick() {
        if (this.soundEnabled) {
            if (this.activeProfile.id === 'snd-piano') {
                const chord = [261.63, 329.63, 392.00]; 
                chord.forEach((f, i) => {
                    setTimeout(() => {
                        this.playTone(f, 0.6, 0.2, 'triangle', undefined, true); 
                    }, i * 12); 
                });
            } else if (this.activeProfile.id === 'snd-wood') {
                // Dry hollow click
                this.playTone(330, 0.1, 0.4, 'sine', undefined, true);
            } else if (this.activeProfile.id === 'snd-water') {
                // High bubble click
                this.playTone(800, 0.08, 0.3, 'sine', undefined, true);
            } else {
                this.playTone(this.activeProfile.uiClickFreq, this.activeProfile.duration, 0.4);
            }
        }

        if (this.vibrationEnabled) {
            Haptics.impact({ style: ImpactStyle.Light });
        }
    }

    playTap() {
        if (this.soundEnabled) {
            let freq = this.activeProfile.uiTapFreq;
            if (this.activeProfile.tapFreqs && this.activeProfile.tapFreqs.length > 0) {
                freq = this.activeProfile.tapFreqs[Math.floor(Math.random() * this.activeProfile.tapFreqs.length)];
            }
            this.playTone(freq, this.activeProfile.duration, 0.4);
        }
        if (this.vibrationEnabled) {
            Haptics.selectionStart();
        }
    }

    playNumber(num: number) {
        if (this.soundEnabled) {
            const freq = this.activeProfile.numberFreqs[num - 1] || 600;
            const vol = 0.6;
            this.playTone(freq, this.activeProfile.duration, vol);
        }
        if (this.vibrationEnabled) {
            Haptics.impact({ style: ImpactStyle.Medium });
        }
    }

    playPop() {
        if (this.soundEnabled) {
            // New Fun Pop: Quick upward sweep
            const ctx = this.getCtx();
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();

            osc.type = 'sine';
            // Start low, go high quickly
            osc.frequency.setValueAtTime(400, ctx.currentTime);
            osc.frequency.exponentialRampToValueAtTime(800, ctx.currentTime + 0.1);

            gain.gain.setValueAtTime(0, ctx.currentTime);
            gain.gain.linearRampToValueAtTime(0.5, ctx.currentTime + 0.01);
            gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.1);

            osc.connect(gain);
            gain.connect(ctx.destination);

            osc.start();
            osc.stop(ctx.currentTime + 0.15);
        }
        if (this.vibrationEnabled) {
            Haptics.impact({ style: ImpactStyle.Light });
        }
    }

    playBubblePop() {
        if (this.soundEnabled) {
            const ctx = this.getCtx();
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();

            // "Bloop" - start lower, rise fast, short decay
            osc.type = 'sine';
            osc.frequency.setValueAtTime(300, ctx.currentTime);
            osc.frequency.exponentialRampToValueAtTime(600, ctx.currentTime + 0.1);

            gain.gain.setValueAtTime(0, ctx.currentTime);
            gain.gain.linearRampToValueAtTime(0.8, ctx.currentTime + 0.01); // Fast attack
            gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.1); // Short decay

            osc.connect(gain);
            gain.connect(ctx.destination);

            osc.start();
            osc.stop(ctx.currentTime + 0.15);
        }
        if (this.vibrationEnabled) {
            Haptics.impact({ style: ImpactStyle.Light });
        }
    }

    playPepinoTap() {
        if (this.soundEnabled) {
            const ctx = this.getCtx();
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();

            // "Tiny Blip" - Cute and tactile
            // A5 (880Hz) to A6 (1760Hz) fast chirp
            osc.type = 'sine';
            osc.frequency.setValueAtTime(880, ctx.currentTime); 
            osc.frequency.exponentialRampToValueAtTime(1760, ctx.currentTime + 0.05); 

            gain.gain.setValueAtTime(0, ctx.currentTime);
            gain.gain.linearRampToValueAtTime(0.15, ctx.currentTime + 0.01); 
            gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.1); 

            osc.connect(gain);
            gain.connect(ctx.destination);

            osc.start();
            osc.stop(ctx.currentTime + 0.15);
        }
        // Light impact for tactility
        if (this.vibrationEnabled) {
            Haptics.impact({ style: ImpactStyle.Light });
        }
    }

    playCounterTick() {
        if (!this.soundEnabled) return;

        // Throttling to avoid buzzing on large number jumps
        const now = Date.now();
        if (now - this.lastTickTime < 50) return; 
        this.lastTickTime = now;

        const pid = this.activeProfile.id;

        if (pid === 'snd-paper') {
            this.playNoiseBurst(1500, 0.01, 0.15); // Very short scratch
        } else if (pid === 'snd-wood') {
            this.playTone(800, 0.02, 0.15, 'sine', undefined, true);
        } else if (pid === 'snd-water') {
            this.playTone(1000 + Math.random() * 200, 0.03, 0.15, 'sine', undefined, true);
        } else if (pid === 'snd-piano') {
            // High C7 is ~2093
            this.playTone(2093, 0.05, 0.1, 'triangle', undefined, true);
        } else {
            // Zen / Default
            this.playTone(1000, 0.02, 0.1, 'sine', undefined, true);
        }
    }

    playProgressFill(duration: number): () => void {
        if (!this.soundEnabled) return () => {};
        const ctx = this.getCtx();
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        const filter = ctx.createBiquadFilter();

        // Subtle rising tone ("charging" effect)
        osc.type = 'sine';
        osc.frequency.setValueAtTime(150, ctx.currentTime);
        // Ramp pitch slightly
        osc.frequency.exponentialRampToValueAtTime(400, ctx.currentTime + duration);

        // Lowpass filter opening up
        filter.type = 'lowpass';
        filter.frequency.setValueAtTime(200, ctx.currentTime);
        filter.frequency.linearRampToValueAtTime(800, ctx.currentTime + duration);

        gain.gain.setValueAtTime(0, ctx.currentTime);
        // Soft fade in
        gain.gain.linearRampToValueAtTime(0.05, ctx.currentTime + 0.2);
        // Hold
        gain.gain.linearRampToValueAtTime(0.05, ctx.currentTime + duration - 0.2);
        // Soft fade out
        gain.gain.linearRampToValueAtTime(0, ctx.currentTime + duration);

        osc.connect(filter);
        filter.connect(gain);
        gain.connect(ctx.destination);

        osc.start();
        osc.stop(ctx.currentTime + duration);

        return () => {
            try {
                // Ramp down quickly to avoid click on stop
                gain.gain.cancelScheduledValues(ctx.currentTime);
                gain.gain.setValueAtTime(gain.gain.value, ctx.currentTime);
                gain.gain.linearRampToValueAtTime(0, ctx.currentTime + 0.1);
                osc.stop(ctx.currentTime + 0.15);
            } catch(e) {}
        };
    }

    playUnlockReady() {
        if (!this.soundEnabled) return;
        const ctx = this.getCtx();

        // "Unlock Ready" Chime: Bright, Magical
        // C6, E6, G6, C7
        const notes = [1046.50, 1318.51, 1567.98, 2093.00];

        notes.forEach((freq, i) => {
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();

            osc.type = 'sine';
            osc.frequency.setValueAtTime(freq, ctx.currentTime);

            const start = ctx.currentTime + (i * 0.08); // Slight stagger

            gain.gain.setValueAtTime(0, start);
            gain.gain.linearRampToValueAtTime(0.1, start + 0.02);
            gain.gain.exponentialRampToValueAtTime(0.001, start + 1.5);

            osc.connect(gain);
            gain.connect(ctx.destination);

            osc.start(start);
            osc.stop(start + 1.6);
        });

        if (this.vibrationEnabled) {
             Haptics.notification({ type: NotificationType.Success });
        }
    }

    playWin() {
        if (this.soundEnabled) {
            const sequence = [1046.50, 1318.51, 1567.98, 2093.00]; 
            const timings = [0, 60, 120, 180]; 

            sequence.forEach((freq, i) => {
                setTimeout(() => {
                    const ctx = this.getCtx();
                    const osc = ctx.createOscillator();
                    const gain = ctx.createGain();
                    osc.type = 'sine';
                    osc.frequency.setValueAtTime(freq, ctx.currentTime);
                    gain.gain.setValueAtTime(0, ctx.currentTime);
                    gain.gain.linearRampToValueAtTime(0.25, ctx.currentTime + 0.01);
                    gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.2);
                    osc.connect(gain);
                    gain.connect(ctx.destination);
                    osc.start();
                    osc.stop(ctx.currentTime + 0.25);
                }, timings[i]);
            });
        }
        if (this.vibrationEnabled) {
            Haptics.notification({ type: NotificationType.Success });
        }
    }

    playLevelEnter() {
        if (!this.soundEnabled) return;

        const pid = this.activeProfile.id;

        if (pid === 'snd-paper') {
            this.playNoiseBurst(600, 0.15, 0.5);
            setTimeout(() => this.playNoiseBurst(1000, 0.1, 0.3), 100);

        } else if (pid === 'snd-wood') {
            // Forest Rattle: Random pentatonic notes
            const notes = [440, 587, 659, 783]; 
            notes.forEach((f, i) => {
                const delay = i * 40 + (Math.random() * 30);
                setTimeout(() => {
                    this.playTone(f, 0.1, 0.3, 'sine', undefined, true);
                }, delay);
            });

        } else if (pid === 'snd-water') {
             // River Stream: Rapid bubbling cascade
             const notes = [800, 700, 600, 500];
             notes.forEach((f, i) => {
                 setTimeout(() => this.playTone(f, 0.08, 0.3), i * 60);
             });

        } else if (pid === 'snd-piano') {
            const notes = [261.63, 329.63, 392.00, 493.88];
            notes.forEach((f, i) => {
                setTimeout(() => this.playTone(f, 1.0, 0.4, 'triangle', undefined, false), i * 60);
            });
        } else {
            const d = 0.035; 
            this.playTone(1200, d, 0.5, 'sine', undefined, true); 
            setTimeout(() => {
                this.playTone(1600, d, 0.5, 'sine', undefined, true);
            }, 60); 
        }
    }

    playZap() {
        // "Auto" Skill Sound - Satisfying "Snap + Ding"
        if (this.soundEnabled) {
            const ctx = this.getCtx();
            const now = ctx.currentTime;

            // 1. The Snap (Percussive, Mechanical)
            const snapOsc = ctx.createOscillator();
            const snapGain = ctx.createGain();

            snapOsc.type = 'triangle'; // Sharper than sine
            snapOsc.frequency.setValueAtTime(300, now);
            snapOsc.frequency.exponentialRampToValueAtTime(50, now + 0.1); // Quick drop

            snapGain.gain.setValueAtTime(0, now);
            snapGain.gain.linearRampToValueAtTime(0.4, now + 0.01);
            snapGain.gain.exponentialRampToValueAtTime(0.001, now + 0.1);

            snapOsc.connect(snapGain);
            snapGain.connect(ctx.destination);
            snapOsc.start(now);
            snapOsc.stop(now + 0.15);

            // 2. The Ding (Confirmation, High Pitch)
            const dingOsc = ctx.createOscillator();
            const dingGain = ctx.createGain();

            dingOsc.type = 'sine';
            dingOsc.frequency.setValueAtTime(1046.50, now); // C6

            dingGain.gain.setValueAtTime(0, now);
            dingGain.gain.linearRampToValueAtTime(0.2, now + 0.02);
            dingGain.gain.exponentialRampToValueAtTime(0.001, now + 0.4);

            dingOsc.connect(dingGain);
            dingGain.connect(ctx.destination);
            dingOsc.start(now);
            dingOsc.stop(now + 0.45);
        }

        if (this.vibrationEnabled) {
            Haptics.impact({ style: ImpactStyle.Medium });
        }
    }

    playScan() {
        if (this.soundEnabled) {
            const ctx = this.getCtx();
            const now = ctx.currentTime;
            const duration = 1.2;

            const tikOsc = ctx.createOscillator();
            const tikGain = ctx.createGain();
            tikOsc.type = 'square';
            tikOsc.frequency.setValueAtTime(2500, now);
            tikGain.gain.setValueAtTime(0, now);
            for(let i = 0; i < 12; i++) {
                const t = now + (i * (duration / 12));
                tikGain.gain.setTargetAtTime(0.06, t, 0.005);
                tikGain.gain.setTargetAtTime(0, t + 0.02, 0.005);
            }
            tikOsc.connect(tikGain);
            tikGain.connect(ctx.destination);
            tikOsc.start(now);
            tikOsc.stop(now + duration);

            const bzzOsc = ctx.createOscillator();
            const bzzGain = ctx.createGain();
            bzzOsc.type = 'sawtooth';
            bzzOsc.frequency.setValueAtTime(120, now);
            bzzOsc.frequency.exponentialRampToValueAtTime(400, now + duration);
            bzzGain.gain.setValueAtTime(0, now);
            bzzGain.gain.linearRampToValueAtTime(0.045, now + 0.2); 
            bzzGain.gain.exponentialRampToValueAtTime(0.001, now + duration);
            bzzOsc.connect(bzzGain);
            bzzGain.connect(ctx.destination);
            bzzOsc.start(now);
            bzzOsc.stop(now + duration);

            const chimeOsc = ctx.createOscillator();
            const chimeGain = ctx.createGain();
            chimeOsc.type = 'sine';
            chimeOsc.frequency.setValueAtTime(783.99, now + 0.3); 
            chimeOsc.frequency.exponentialRampToValueAtTime(1046.50, now + duration); 
            chimeGain.gain.setValueAtTime(0, now);
            chimeGain.gain.setTargetAtTime(0.0675, now + 0.4, 0.2); 
            chimeGain.gain.exponentialRampToValueAtTime(0.001, now + duration);
            chimeOsc.connect(chimeGain);
            chimeGain.connect(ctx.destination);
            chimeOsc.start(now + 0.3);
            chimeOsc.stop(now + duration);

            const bufferSize = ctx.sampleRate * 0.5;
            const noiseBuffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
            const output = noiseBuffer.getChannelData(0);
            for (let i = 0; i < bufferSize; i++) {
                output[i] = Math.random() * 2 - 1;
            }
            const whiteNoise = ctx.createBufferSource();
            whiteNoise.buffer = noiseBuffer;
            const noiseGain = ctx.createGain();
            noiseGain.gain.setValueAtTime(0, now + duration - 0.4);
            noiseGain.gain.linearRampToValueAtTime(0.016875, now + duration - 0.2);
            noiseGain.gain.exponentialRampToValueAtTime(0.001, now + duration);
            whiteNoise.connect(noiseGain);
            noiseGain.connect(ctx.destination);
            whiteNoise.start(now + duration - 0.4);
        }

        if (this.vibrationEnabled) {
            Haptics.impact({ style: ImpactStyle.Medium });
            setTimeout(() => { if (this.vibrationEnabled) Haptics.impact({ style: ImpactStyle.Light }); }, 600);
        }
    }

    playReveal() {
        if (!this.soundEnabled) return;
        const ctx = this.getCtx();
        const now = ctx.currentTime;

        // Consistent "Magical" Chord: C Major Add9 (C, E, G, D)
        // This plays regardless of the selected sound pack
        const frequencies = [523.25, 659.25, 783.99, 1174.66]; 

        frequencies.forEach((freq, i) => {
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();

            // Use Sine for pure magic sound
            osc.type = 'sine';
            osc.frequency.setValueAtTime(freq, now);

            // Staggered entry for "shimmer" effect
            const startTime = now + (i * 0.06);

            gain.gain.setValueAtTime(0, startTime);
            gain.gain.linearRampToValueAtTime(0.15, startTime + 0.05); // Soft attack
            gain.gain.exponentialRampToValueAtTime(0.001, startTime + 1.2); // Long decay

            osc.connect(gain);
            gain.connect(ctx.destination);

            osc.start(startTime);
            osc.stop(startTime + 1.3);
        });
    }

    playPreview(profileId: string) {
        if (!this.soundEnabled) return;

        if (profileId === 'snd-glass') profileId = 'snd-water';
        if (profileId === 'snd-celeste') profileId = 'snd-piano';

        const profile = PROFILES[profileId];
        if (!profile) return;

        // Play the 5th number frequency as a sample
        const freq = profile.numberFreqs[4]; 

        if (profile.type === 'noise') {
             this.playNoiseBurst(profile.noiseFilterFreq || 800, profile.duration, 0.6);
        } else {
             // Preview uses playTone logic directly to match synthesis
             // Pass the profile explicitly to playTone so it uses the correct synthesis logic
             this.playTone(freq, profile.duration, 0.5, undefined, undefined, undefined, profile);
        }
    }
}

