    setSelectedSoundPackId(id);
  };

  const handleToggleSkill = (id: string) => {
    const next = Storage.toggleSkillEnabled(id);
    setEnabledSkills([...next]);
  };

  // Simplified Earn Points Handler (No Fly-In)
  const handleEarnPoints = (amount: number) => {
    const newTotal = Storage.addPoints(amount);
    setPoints(newTotal);
  };

  const handleClaimBonus = (e: React.MouseEvent) => {
    const now = Date.now();
    if (now < nextBonusClaimTime) return;
    sounds.playWin();

    // Set next claim time to next midnight (00:00:00)
    const nextDate = new Date();
    nextDate.setDate(nextDate.getDate() + 1);
    nextDate.setHours(0, 0, 0, 0);
    const nextTime = nextDate.getTime();

    Storage.setNextBonusClaimTime(nextTime);
    setNextBonusClaimTime(nextTime);
    handleEarnPoints(10);
  };

  const initiatePurchase = (item: any, type: 'bg' | 'num' | 'skill' | 'sound') => {
      // Don't play the default 'pop' sound if we are buying a sound pack, 
      // as the preview of that sound pack will already be playing.
      if (type !== 'sound') {
          sounds.playPop();
      }
      setPurchaseCandidate({ ...item, type });
  };

  const confirmPurchase = () => {
      if (!purchaseCandidate) return;
      if (points >= purchaseCandidate.cost) {
          if (purchaseCandidate.type === 'bg') {
             if(Storage.purchaseBackground(purchaseCandidate.id, purchaseCandidate.cost)) {
                setPurchasedBackgrounds([...purchasedBackgrounds, purchaseCandidate.id]);
                handleSelectBackground(purchaseCandidate.id);
             }
          } else if (purchaseCandidate.type === 'num') {
             if(Storage.purchaseNumberColor(purchaseCandidate.id, purchaseCandidate.cost)) {
                setPurchasedNumberColors([...purchasedNumberColors, purchaseCandidate.id]);
                handleSelectNumberColor(purchaseCandidate.id);
             }
          } else if (purchaseCandidate.type === 'skill') {
             if(Storage.purchaseSkill(purchaseCandidate.id, purchaseCandidate.cost)) {
                setPurchasedSkills(Storage.getPurchasedSkills());
                setEnabledSkills(Storage.getEnabledSkills());
             }
          } else if (purchaseCandidate.type === 'sound') {
            if(Storage.purchaseSoundPack(purchaseCandidate.id, purchaseCandidate.cost)) {
               setPurchasedSoundPacks([...purchasedSoundPacks, purchaseCandidate.id]);
               handleSelectSoundPack(purchaseCandidate.id);
            }
          }
          setPoints(Storage.getPoints());
          setPurchaseCandidate(null);
      } else {
          setPurchaseCandidate(null);
          setShowNotEnoughPoints(true);
      }
  };

  const handleWatchAd = async () => {
        setShowNotEnoughPoints(false);
        setPurchaseCandidate(null);
        // Show the internal 'fake' ad overlay which provides rewards
        setIsWatchingAd(true);
  };

  const handleAdReward = () => {
      handleEarnPoints(25);
      setIsWatchingAd(false);
      sounds.playWin();
  };

  const handleNavigateToShop = () => {
      setShowNotEnoughPoints(false);
      navigate('diamondShop', 'forward');
  };

  const handleGoPlay = () => {
      setShowNotEnoughPoints(false);
      setPurchaseCandidate(null);
      if (screen === 'store') {
          navigate('difficulty', 'back');
      }
  };

  const handleBuyOffer = (offer: DiamondOffer) => {
      sounds.playClick();
      // Only check starter pack restriction
      if (offer.type === 'starter' && starterPackPurchased) return;
      if (offer.priceLabel === '') return;
      setPaymentOffer(offer);
  };

  const finalizeRealMoneyPurchase = () => {
      if (!paymentOffer) return;
      const offer = paymentOffer;

      handleEarnPoints(offer.diamonds);

      if (offer.type === 'starter') {
          Storage.setStarterPackPurchased();
          setStarterPackPurchased(true);
          Storage.purchaseSkill('skill-auto', 0);
          Storage.purchaseSkill('skill-scan', 0);
          Storage.purchaseSoundPack('snd-piano', 0);
      } else if (offer.type === 'support') {
          Storage.unlockPepino();
      }

      setPurchasedSkills(Storage.getPurchasedSkills());
      setEnabledSkills(Storage.getEnabledSkills());
      setPurchasedNumberColors(Storage.getPurchasedNumberColors());
      setPurchasedBackgrounds(Storage.getPurchasedBackgrounds());
      setPurchasedSoundPacks(Storage.getPurchasedSoundPacks());
      setPaymentOffer(null);
  };

  const handleUnlockPack2 = () => {
      if (!selectedDifficulty) return;
      const cost = getPackCost(selectedDifficulty, 2);
      if (points >= cost) {
          sounds.playPop();
          if (Storage.unlockPack2(selectedDifficulty, cost)) {
              setPoints(Storage.getPoints());
              setUnlockedPacks2(Storage.getUnlockedPacks2());
              sounds.playWin();
          }
      } else {
          sounds.playClick();
          setShowNotEnoughPoints(true);
      }
  };

  const handleUnlockPack3 = () => {
      if (!selectedDifficulty) return;
      const cost = getPackCost(selectedDifficulty, 3);
      if (points >= cost) {
          sounds.playPop();
          if (Storage.unlockPack3(selectedDifficulty, cost)) {
              setPoints(Storage.getPoints());
              setUnlockedPacks3(Storage.getUnlockedPacks3());
              sounds.playWin();
          }
      } else {
          sounds.playClick();
          setShowNotEnoughPoints(true);
      }
  };

  let activeBackgroundClass = "bg-paper dark:bg-stone-900"; 

  if (selectedBackgroundId) {
      const bg = ALL_BACKGROUNDS.find(b => b.id === selectedBackgroundId);
      if (bg) {
          activeBackgroundClass = bg.class;
      }
  }

  const numberColorClass = NUMBER_COLORS.find(n => n.id === selectedNumberColorId)?.class || 'text-blue-600';
  const isGradient = activeBackgroundClass.includes('bg-gradient');
  let overlayOpacity = '0';
  if (isGradient) {
      if (screen === 'game') {
          overlayOpacity = 'calc(var(--overlay-opacity) * 1.6)';
      } else {
          overlayOpacity = 'var(--overlay-opacity)';
      }
  } else if (screen === 'game') {
      overlayOpacity = 'calc(var(--overlay-opacity) * 0.6)';
  }

  // Animation Variants for "Slide" Transition
  // Using 100% width slide to prevent cuts and ensure screens move completely off-view
  const variants: Variants = {
    initial: (dir: number) => ({
      x: dir > 0 ? '100%' : (dir < 0 ? '-100%' : 0),
      opacity: 0
    }),
    animate: {
      x: 0,
      opacity: 1,
      transition: { 
          type: "spring", 
          stiffness: 260, 
          damping: 25
      }
    },
    exit: (dir: number) => ({
      x: dir > 0 ? '-100%' : '100%',
      opacity: 0,
      transition: { 
          type: "spring", 
          stiffness: 260, 
          damping: 25
      }
    })
  };

  return (
      <>
          {/* Main App Wrapper: Fixed, Full Viewport, No Overflow */}
          <div className="fixed inset-0 z-0 w-full h-full overflow-hidden select-none touch-none">

              {/* Background Layer (Persistent) */}
              <div 
                className={`absolute inset-0 z-0 transition-all ease-in-out duration-500 ${activeBackgroundClass}`} 
                style={{ width: '100%', height: '100%' }}
              />
              <div 
                className="absolute inset-0 z-[1] bg-black pointer-events-none transition-opacity duration-500" 
                style={{ opacity: overlayOpacity }} 
              />

              {/* Diamond Shop Background (Behind Safe Area Wrapper) */}
              {screen === 'diamondShop' && <DiamondBackground />}

              {/* Content Wrapper with Safe Areas */}
              {/* This inner container handles safe area padding to prevent content from being covered by notch/home bar */}
              <div 
                 className="relative z-10 w-full h-full flex flex-col pt-safe pb-safe"
              >
                <div className="flex-1 relative w-full h-full overflow-hidden">
                    <AnimatePresence custom={direction} initial={false}>
                        <motion.div
                            key={screen}
                            custom={direction}
                            variants={variants}
                            initial="initial"
                            animate="animate"
                            exit="exit"
                            className="absolute inset-0 w-full h-full flex flex-col items-center justify-center font-sans text-t-primary overflow-hidden bg-transparent"
                            style={{ pointerEvents: 'auto' }}
                        >
                            {screen === 'splash' && <SplashScreen />}

                            {screen === 'difficulty' && (
                                <DifficultyScreen 
                                    points={points}
                                    onDifficultySelect={handleDifficultySelect}
                                    onOpenSettings={() => setShowSettings(true)}
                                    onOpenStore={() => navigate('store', 'forward')}
                                    onOpenDiamondShop={() => navigate('diamondShop', 'forward')}
                                    onClaimBonus={handleClaimBonus}
                                    onOpenStats={() => navigate('stats', 'forward')}
                                    nextBonusClaimTime={nextBonusClaimTime}
                                    hiddenDifficulties={settings.hiddenDifficulties}
                                />
                            )}

                            {screen === 'diamondShop' && (
                                <DiamondShopScreen 
                                    points={points}
                                    onBack={handleDiamondShopBack}
                                    onWatchAd={handleWatchAd}
                                    onBuyOffer={handleBuyOffer}
                                    onEarnPoints={handleEarnPoints}
                                    starterPackPurchased={starterPackPurchased}
                                />
                            )}

                            {screen === 'stats' && (
                                <StatsScreen 
                                    onBack={handleStatsBack}
                                    onEarnPoints={handleEarnPoints}
                                    points={points}
                                />
                            )}

                            {screen === 'levels' && selectedDifficulty && (
                                <LevelsScreen 
                                    difficulty={selectedDifficulty}
                                    points={points}
                                    unlockedPacks2={unlockedPacks2}
                                    unlockedPacks3={unlockedPacks3}
                                    onBack={handleLevelBack}
                                    onLevelSelect={handleLevelSelect}
                                    onOpenSettings={() => setShowSettings(true)}
                                    onUnlockPack2={handleUnlockPack2}
                                    onUnlockPack3={handleUnlockPack3}
                                />
                            )}

                            {screen === 'store' && (
                                <StoreScreen 
                                    points={points}
                                    onBack={handleStoreBack}
                                    purchasedSkills={purchasedSkills}
                                    enabledSkills={enabledSkills}
                                    purchasedBackgrounds={purchasedBackgrounds}
                                    purchasedNumberColors={purchasedNumberColors}
                                    purchasedSoundPacks={purchasedSoundPacks}
                                    selectedBackgroundId={selectedBackgroundId}
                                    selectedNumberColorId={selectedNumberColorId}
                                    selectedSoundPackId={selectedSoundPackId}
                                    onPurchase={initiatePurchase}
                                    onSelectBackground={handleSelectBackground}
                                    onSelectNumberColor={handleSelectNumberColor}
                                    onSelectSoundPack={handleSelectSoundPack}
                                    onToggleSkill={handleToggleSkill}
                                />
                            )}

                            {screen === 'game' && selectedDifficulty && selectedLevel && (
                                <SudokuGame
                                    difficulty={selectedDifficulty}
                                    levelId={selectedLevel}
                                    onBack={handleGameBack}
                                    onReturnToMenu={handleReturnToMenu}
                                    onComplete={() => {
                                        setPoints(Storage.getPoints());
                                    }}
                                    onSettingsOpen={() => setShowSettings(true)}
                                    settings={settings}
                                    onEarnPoints={handleEarnPoints}
                                    currentPoints={points}
                                    isSettingsOpen={showSettings}
                                    backgroundClass={activeBackgroundClass}
                                    numberColor={numberColorClass}
                                    purchasedSkills={enabledSkills} // Pass only enabled skills to game
                                />
                            )}
                        </motion.div>
                    </AnimatePresence>
                </div>

                {/* Modals & Overlays (Outside AnimatePresence to float on top) */}
                {showSettings && (
                    <SettingsModal 
                        settings={settings} 
                        onToggle={toggleSetting} 
                        onToggleDifficulty={handleToggleDifficultyVisibility}
                        onSetAppearance={setAppearance}
                        onReset={resetProgress}
                        onClose={() => setShowSettings(false)} 
                    />
                )}
                {replayLevelId !== null && selectedDifficulty && (
                    <ReplayModal 
                        levelId={replayLevelId}
                        onConfirm={confirmReplay}
                        onCancel={() => setReplayLevelId(null)}
                    />
                )}
                {purchaseCandidate && (
                    <PurchaseModal 
                        item={purchaseCandidate} 
                        onConfirm={confirmPurchase} 
                        onCancel={() => setPurchaseCandidate(null)} 
                    />
                )}
                {paymentOffer && (
                    <PaymentModal
                        offer={paymentOffer}
                        onComplete={finalizeRealMoneyPurchase}
                        onCancel={() => setPaymentOffer(null)}
                    />
                )}
                {showNotEnoughPoints && (
                    <NotEnoughPointsModal 
                        onClose={() => setShowNotEnoughPoints(false)} 
                        onGetMore={handleNavigateToShop} 
                        onGoPlay={handleGoPlay} 
                    />
                )}
                {/* 
                   Ad Overlay: Since native AdMob is removed, we always trigger this
                   fake overlay when isWatchingAd is true.
                */}
                {isWatchingAd && <AdOverlay onComplete={handleAdReward} />}
              </div>
          </div>
      </>
  );
}

import React, { useMemo } from 'react';
import { Board, Cell, AppSettings } from '../../types';
import SudokuCell from './SudokuCell';

interface SudokuGridProps {
    board: Board;
    selectedCell: [number, number] | null;
    activeNumber: number | null;
    conflicts: Set<string>;
    revealingCell: {r: number, c: number} | null;
    animatingCell: {r: number, c: number, value: number} | null;
    isScanning: boolean;
    animatingSections: Set<string>;
    settings: AppSettings;
    numberColor: string;
    onCellClick: (e: React.MouseEvent, r: number, c: number) => void;
}

export const SudokuGrid: React.FC<SudokuGridProps> = React.memo(({
    board,
    selectedCell,
    activeNumber,
    conflicts,
    revealingCell,
    animatingCell,
    isScanning,
    animatingSections,
    settings,
    numberColor,
    onCellClick
}) => {
    const squareSize = 'min(96vw, 53dvh)';
    const mainFontSize = `calc(${squareSize} / 9 * 0.6)`;
    const noteFontSize = `calc(${squareSize} / 9 * 0.22)`;
    const noteLineHeight = `calc(${squareSize} / 9 * 0.25)`;

    // Calculate the currently highlighted value based on active input or selected cell
    const highlightedValue = useMemo(() => {
        if (activeNumber !== null) return activeNumber;
        if (selectedCell) {
            return board[selectedCell[0]][selectedCell[1]].value;
        }
        return null;
    }, [activeNumber, selectedCell, board]);

    const getSectionOverlayStyle = (sectionId: string) => {
        if (sectionId === 'full-board') {
            return {
                position: 'absolute' as const,
                pointerEvents: 'none' as const,
                zIndex: 60,
                top: 0,
                left: 0,
                width: '100%',
                height: '100%',
                borderWidth: '8px' 
            };
        }

        const [type, idxStr] = sectionId.split('-');
        const index = parseInt(idxStr);
        const style: React.CSSProperties = { position: 'absolute', pointerEvents: 'none', zIndex: 60 };

        if (type === 'row') {
            style.top = `${(index / 9) * 100}%`;
            style.left = '0';
            style.width = '100%';
            style.height = `${100 / 9}%`;
        } else if (type === 'col') {
            style.left = `${(index / 9) * 100}%`;
            style.top = '0';
            style.height = '100%';
            style.width = `${100 / 9}%`;
        } else if (type === 'box') {
            const r = Math.floor(index / 3);
            const c = index % 3;
            style.top = `${(r * 3 / 9) * 100}%`;
            style.left = `${(c * 3 / 9) * 100}%`;
            style.width = `${100 / 3}%`;
            style.height = `${100 / 3}%`;
        }
        return style;
    };

    return (
        <div className="flex-none w-full flex flex-col items-center justify-start min-h-0 px-0 pb-2 pt-[10px]">
            <div 
                className="bg-stone-900 rounded-lg overflow-hidden relative flex-none shadow-lg border-[3px] border-stone-900" 
                style={{ 
                    width: squareSize, 
                    height: squareSize, 
                    maxWidth: '500px', 
                    maxHeight: '500px'
                }}
            >

            {isScanning && (
                <div className="absolute left-0 right-0 h-1 bg-red-500 shadow-[0_0_15px_rgba(239,68,68,0.8)] z-30 animate-scan pointer-events-none"></div>
            )}

            <div className="absolute inset-0 pointer-events-none z-20">
                <svg width="100%" height="100%" viewBox="0 0 9 9" fill="none" xmlns="http://www.w3.org/2000/svg" style={{ display: 'block' }}>
                    <defs><style>{`.grid-line-thin { stroke: #57534e; stroke-width: 0.025; } .grid-line-thick { stroke: #1c1917; stroke-width: 0.08; } `}</style></defs>
                    <line x1="1" y1="0" x2="1" y2="9" className="grid-line-thin" /><line x1="2" y1="0" x2="2" y2="9" className="grid-line-thin" />
                    <line x1="4" y1="0" x2="4" y2="9" className="grid-line-thin" /><line x1="5" y1="0" x2="5" y2="9" className="grid-line-thin" />
                    <line x1="7" y1="0" x2="7" y2="9" className="grid-line-thin" /><line x1="8" y1="0" x2="8" y2="9" className="grid-line-thin" />
                    <line x1="0" y1="1" x2="9" y2="1" className="grid-line-thin" /><line x1="0" y1="2" x2="9" y2="2" className="grid-line-thin" />
                    <line x1="0" y1="4" x2="9" y2="4" className="grid-line-thin" /><line x1="0" y1="5" x2="9" y2="5" className="grid-line-thin" />
                    <line x1="0" y1="7" x2="9" y2="7" className="grid-line-thin" /><line x1="0" y1="8" x2="9" y2="8" className="grid-line-thin" />
                    <line x1="3" y1="0" x2="3" y2="9" className="grid-line-thick" /><line x1="6" y1="0" x2="6" y2="9" className="grid-line-thick" />
                    <line x1="0" y1="3" x2="9" y2="3" className="grid-line-thick" /><line x1="0" y1="6" x2="9" y2="6" className="grid-line-thick" />
                </svg>
            </div>

            <div className="grid w-full h-full relative z-10" style={{ gridTemplateColumns: 'repeat(9, minmax(0, 1fr))', gridTemplateRows: 'repeat(9, minmax(0, 1fr))' }}>
            {board.map((row, rIndex) => row.map((cell, cIndex) => {
                    const isAnimating = animatingCell?.r === rIndex && animatingCell?.c === cIndex;
                    const isConflict = conflicts.has(`${rIndex}-${cIndex}`);

                    const isSelected = selectedCell ? (selectedCell[0] === rIndex && selectedCell[1] === cIndex) : false;

                    let isSameValue = false;
                    if (cell.value !== null && highlightedValue !== null) {
                        isSameValue = cell.value === highlightedValue;
                    }

                    const isRelated = selectedCell && (selectedCell[0] === rIndex || selectedCell[1] === cIndex || (Math.floor(selectedCell[0]/3) === Math.floor(rIndex/3) && Math.floor(selectedCell[1]/3) === Math.floor(cIndex/3)));

                    const isRevealingCell = revealingCell?.r === rIndex && revealingCell?.c === cIndex;

                    return (
                        <SudokuCell
                            key={`${rIndex}-${cIndex}`}
                            r={rIndex}
                            c={cIndex}
                            cell={cell}
                            isConflict={isConflict}
                            isError={!!cell.isError}
                            isMarkedWrong={!!cell.isMarkedWrong}
                            isRevealed={!!cell.isRevealed}
                            isSelected={isSelected}
                            isSameValue={isSameValue}
                            isRelated={!!isRelated}
                            highlight={settings.highlight}
                            isRevealingCell={isRevealingCell}
                            animatingValue={isAnimating ? animatingCell!.value : null}
                            settings={settings}
                            numberColor={numberColor}
                            onCellClick={onCellClick}
                            mainFontSize={mainFontSize}
                            noteFontSize={noteFontSize}
                            noteLineHeight={noteLineHeight}
                        />
                    );
                })
            )}
            </div>

            {Array.from(animatingSections).map((sectionId: string) => (
                 <div 
                    key={sectionId} 
                    className={`absolute box-border border-emerald-300 shadow-[0_0_30px_rgba(16,185,129,0.9)] animate-section-complete ${sectionId === 'full-board' ? 'rounded-lg border-4' : 'rounded-sm border-2'}`}
                    style={getSectionOverlayStyle(sectionId)}
                 />
            ))}
         </div>
         </div>
    );
});

